/* === Reset & Base === */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-primary: #1e2d44;
  --color-primary-dark: #0f1a2e;
  --color-primary-light: #3a4a63;
  --color-bg: #ffffff;
  /* Page canvas — a soft off-white behind every page's content so white cards
     read as raised surfaces (#img153). Components keep --color-bg for their own
     white fills. */
  --color-page: #f4f5f9;
  --color-bg-light: #f7f8fa;
  --color-bg-muted: #f0f4f8;
  /* Light cool-gray "surface" — the homepage search card and all takeover/modal
     panels share this so clicking the home search lifts cleanly into the modal.
     Inner inputs/result wells stay white to read as depth on the gray. */
  --color-surface: #f6f7f9;
  --color-surface-border: #e8eaef;
  --color-text: #2d3748;
  --color-text-muted: #718096;
  --color-text-light: #a0aec0;
  --color-border: #e2e8f0;
  --color-border-light: #f0f0f0;
  --color-accent: #e8ecf5;
  --color-danger: #e53e3e;
  --color-success: #38a169;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  /* General Sans — humanist sans for display roles (section titles,
     brand wordmark, topic banner). Loaded from Fontshare (see
     index.html) as discrete weights (300..700). For sub-step
     weight needs (between 500 and 600, etc.) we use a small
     text-shadow trick on the specific selector — see the
     .news-card-title and section-title comments. */
  --font-display: 'General Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  /* revamp904: 1440 -> 1760. On 1920+ monitors the old cap left ~240px of dead
     gutter each side; 1760 uses that space while keeping text at a readable
     measure. One token drives all 18 consumers, so every page moves together. */
  --max-width: 1760px;
  --header-height: 60px;
  /* Main-nav (sticky hero) height. Desktop 64px; mobile shrinks it (#1) — every
     fixed-layout offset that reserves the nav reads this var instead of a literal
     64px, so the trim cascades correctly. */
  --nav-h: 56px;   /* revamp1004: one 56px chrome contract everywhere */
}
@media (max-width: 899.98px) { :root { --nav-h: 56px; } }

/* Form controls (button/input/select/textarea) do NOT inherit font-family from
   the document — the UA stylesheet forces a platform system font, so any control
   without an explicit font rendered in Segoe UI on Windows / San Francisco on Mac
   instead of Inter (#img648). One global inherit fixes the whole class site-wide. */
button, input, select, textarea, optgroup { font-family: inherit; font-size: inherit; }

body {
  font-family: var(--font-family);
  color: var(--color-text);
  background: var(--color-page);
  line-height: 1.6;
  /* Suppress the iOS double-tap-to-zoom delay on interactive
     elements site-wide. Pinch-zoom still works (we don't set
     user-scalable=no on the viewport), but accidental zoom on
     repeated quick taps in topic pickers / chip strips is gone. */
  touch-action: manipulation;
  /* Disable iOS tap highlight (the grey/blue flash that lingers
     on tapped links and carries over to the next page when the
     same x/y is hit). */
  -webkit-tap-highlight-color: transparent;
}

/* iOS: focusing a field whose font-size is under 16px auto-zooms the page — and a
   zoomed viewport un-pins fixed/sticky chrome, which read as "the search header
   scrolls / weird gap above it" on phones (#img37). Floor every field at 16px on
   touch widths so the zoom never triggers. */
@media (max-width: 767px) {
  input, select, textarea { font-size: max(16px, 1em) !important; }
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

/* Underline on hover only on hover-capable pointers. On touch
   devices the brief :hover state from a tap was leaving links
   underlined on the next page (carryover-click). */
@media (hover: hover) and (pointer: fine) {
  a:hover {
    text-decoration: underline;
  }
}

#app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

#content {
  flex: 1;
  max-width: var(--max-width);
  width: 100%;
  margin: 0 auto;
  padding: 1.5rem 2rem;
}

/* The single-row nav keeps its comfortable 2rem side padding all the way down to
   the two-row breakpoint (561), so the content column's left edge stays aligned
   with the nav across every single-row width — no jarring jump to a jammed-left
   1rem at ≤899 (#img160/#img161). Only phones (≤560, two-row) tighten to 1rem. */
@media (max-width: 560px) {
  #content {
    padding-left: 1rem;
    padding-right: 1rem;
  }
}

/* === Header === */
#site-header {
  background: var(--color-primary);
  color: white;
}

/* === Hero (homepage only, desktop) === */
#hero {
  background: linear-gradient(180deg, var(--color-bg-light) 0%, var(--color-bg) 100%);
  border-bottom: 1px solid rgba(30, 45, 68, 0.08);
}

#hero:empty {
  display: none;
}

/* On home, ensure content can always be scrolled past the hero so that
   tab-switching while in the sticky-revealed state stays revealed
   (otherwise, a short tab's content would let the browser clamp the
   scroll back down below the threshold). */
body.home-mode #content {
  min-height: 100vh;
}

/* Hidden on mobile — mobile home goes straight into sticky nav + subnav */
@media (max-width: 640px) {
  #hero {
    display: none;
  }
}

/* ====================================================================
   Sticky main nav (dark navy). Behavior:
   - Home: hidden on load, slides in past 180px scroll
   - Other pages: always visible from page load
   ==================================================================== */
#site-header.is-sticky-hero {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  /* Above the nav-dropdown overlay (480) + panel (481) so a click on any nav icon
     always reaches the icon — never gets swallowed by the dim overlay — letting you
     switch dropdowns freely while one is open (#img178). Still below full takeover
     modals (1000+). */
  z-index: 490;
  background: var(--color-primary-dark);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  opacity: 0;
  transform: translateY(-100%);
  transition: opacity 0.22s ease, transform 0.22s ease;
  pointer-events: none;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
}

#site-header.is-sticky-hero.is-revealed {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

/* Content padding when fixed headers are always visible (non-home pages).
   Main nav: 56px desktop / 100px mobile.
   Subnav (when present): ~62px desktop / ~62px mobile (incl. top padding).
   Add breathing room beneath the final fixed band. */
body.sticky-always #content {
  padding-top: calc(var(--nav-h) + 2rem);
}

body.sticky-always.has-subnav #content {
  padding-top: calc(var(--nav-h) + var(--subnav-height, 66px) + 1.75rem);
}

/* Custom-search pages have no subnav — sit content just below the
   main nav with a small gap (not the subnav-sized reservation that
   left a weird void above the title). The in-page sticky bar pins to
   the nav as the user scrolls. */
body.custom-mode.sticky-always #content {
  padding-top: calc(var(--nav-h) + 0.85rem);
}


@media (max-width: 640px) {
  body.sticky-always #content {
    padding-top: calc(var(--nav-h) + 1.5rem);
  }

  body.sticky-always.has-subnav #content {
    padding-top: calc(var(--nav-h) + var(--subnav-height, 66px) + 1rem);
  }

  body.custom-mode.sticky-always #content {
    padding-top: calc(var(--nav-h) + 1rem);
  }
}

/* Nav band: 56px desktop. Controls at 30px so they sit comfortably inside
   the band with 13px of breathing room above and below. Logo 30px matches. */
.sticky-hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  min-height: var(--nav-h);
}
/* At tabbed-nav widths (≤899px) the subnav drops to 1rem horizontal
   padding to give the title + chips more room. Main nav matches so
   the two bands' left edges align — otherwise the subnav title was
   sitting 16px further left than the main nav brand, looking like
   a layout error. */
/* (Single-row nav keeps 2rem side padding down to 561; the ≤560 two-row block
   sets its own tighter padding. No 1rem drop at ≤899 anymore — #img160.) */
/* Title + tagline share line-height so their text baselines land
   at the same y inside the flex row. Mismatched line-heights here
   center the line BOXES but offset the actual letterforms inside
   them, reading as a few-pixel vertical drift. */
.sticky-title {
  line-height: 1.3;
}

.sticky-brand {
  display: inline-flex;
  align-items: center;
  color: white;
  text-decoration: none;
  flex-shrink: 0;
}

@media (hover: hover) { .sticky-brand:hover {
  text-decoration: none;
} }

.sticky-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 600;
  color: white;
  letter-spacing: -0.028em;
}

/* Desktop topic nav in the main bar — light links on the navy band, the active
   top-level topic underlined. Takes the middle (flex:1) like the old tagline.
   Hidden below 1024px (mobile gets a bottom tab nav). */
/* Featured-topic links are no longer shown in the main nav at ANY width — the nav
   is just the brand + the app icons (#img140). */
.sticky-nav-topics { display: none !important; }
.sticky-nav-topic, .sticky-nav-more {
  position: relative; white-space: nowrap; flex: 0 0 auto;
  font-family: var(--font-family); font-size: 0.85rem; font-weight: 600; letter-spacing: -0.004em;
  color: rgba(255, 255, 255, 0.68); text-decoration: none; padding: 0.25rem 0;
  background: none; border: none; cursor: pointer; transition: color 0.14s;
}
@media (hover: hover) { .sticky-nav-topic:hover, .sticky-nav-more:hover { color: #fff; text-decoration: none; } }
.sticky-nav-topic.is-active { color: #fff; }
.sticky-nav-topic.is-active::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -2px; height: 2px;
  background: #5b8def; border-radius: 2px;
}
.sticky-nav-more { display: inline-flex; align-items: center; gap: 3px; }
.sticky-nav-more svg { opacity: 0.85; }
/* Desktop home: the featured topics live in the SUBNAV ("Featured | …"), NOT in
   the main bar — so drop the main-bar topic nav entirely on home and keep the
   subnav visible at every width (was: main-bar topics replaced a hidden subnav). */
@media (min-width: 1024px) {
  body.home-search .sticky-nav-topics { display: none !important; }
  /* Icon-only Search + Trending in the nav. */
  body.home-search .sticky-actions .search-bar-label { display: none; }
}

/* Search + CTA always right-aligned as a group. Natural-width
   (flex: 0 0 auto) so the tagline in the middle can claim the
   leftover space via its own flex: 1 — otherwise actions and
   tagline split the middle 50/50 and leave a visible gap between
   the brand and the actions group. */
.sticky-actions {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex: 0 0 auto;
  margin-left: auto;
}
/* ONE single-row nav design for EVERY width above the two-row breakpoint (≥561):
   hamburger + site title + a separator, then the app icons sit right after the
   title (padded off it), left-grouped — NOT buried at the far right. This is the
   only design between the widest screens and the point where the hamburger/title
   move to their own row above the icons (≤560). No in-between breakpoint variants
   (#img157/#img158). */
@media (min-width: 561px) {
  .sticky-hero-inner .sticky-actions.navbtns { order: 1; margin-left: 1.75rem !important; margin-right: 0; }
  /* Compact bar, but the icon buttons get real vertical room so the active/open
     pill has breathing space above the icon + below the label (#img191). */
  :root { --nav-h: 56px; }   /* revamp1005b: the 56px contract */
  .sticky-hero-inner .sticky-title { font-size: 1.28rem; }
  .sticky-hero-inner .nav-hamburger { width: 20px; height: 15px; }
  .sticky-hero-inner .navbtn-ico svg { width: 18px; height: 18px; }
  /* Compact padding/label only in the STACKED fallback — horizontal buttons keep
     their roomier padding + readable inline label. */
  .sticky-hero-inner.nav-stacked .navbtn-label { font-size: 0.87rem; }
}

/* Search Topics + Prompt Builder share the same white-pill CTA
   style and sit side-by-side on the right of the dark nav. The
   search button (.sticky-search .search-bar) is a click-through
   trigger that opens the full-screen search overlay; the Prompt
   Builder is an anchor. Both render as identical pills with a
   leading icon and a label. */
/* Pill chips on the dark nav — toned down from stark white to a
   soft cool-slate (#dde3ec). Reads as a quiet utility chip rather
   than a high-contrast CTA, so the nav has less visual shouting.
   Hover lifts to brighter slate, keeping a subtle response without
   going full white. */

/* Prompt Builder CTA — twin of the Search Topics pill above. */

/* Trending pill — sits next to Choose Topics; opens the global Trending
   modal. Neutral pill (matches the other nav pills) with a warm flame
   icon hinting at "what's hot". Visible at every viewport. */

/* Settings gear — sits next to the Prompt Builder pill in the
   main nav. Visible at every viewport so users always have a
   one-tap path to their preferences. */

/* Home shortcut — sits to the right of the gear in the main nav.
   Same color treatment as the gear (dark nav button) but stays
   visible at every viewport width so users always have a one-tap
   path back to the homepage. */

/* ── Desktop main-nav action cluster (2026-06-11) ─────────────────────
   New treatment from the mockup: bare MUTED icons on the navy bar, a
   solid WHITE pill for the active page, and a single "Topics" text-pill
   at the end. Replaces the old row of identical slate icon-pills. Scoped
   to ≥900px — the sub-900 nav is handled by the upcoming mobile overhaul. */
@media (min-width: 900px) {
  /* Every action is a uniform translucent pill (the Topics-chip family);
     the active page turns solid white. Even, deliberate gaps. */
  .sticky-actions { gap: 0.5rem; }
  /* drop the inline text labels — these become pure icons */
  /* Normalize every action glyph: one size, one stroke, a touch larger so they
     fill the pill and read crisply (#15/#36). */
  /* hover — brighter pill, icon to full white */
  /* active PAGE → solid white pill, dark-navy icon */
  /* Topics — same pill family, with its label. */
}

/* Topics pill stays an icon-only chip below the desktop breakpoint. */

/* ═══════════════ Mobile bottom tab nav (2026-06-11) ═══════════════════
   theScore-style fixed bottom bar — Home / Search / Trending / Topics.
   Rendered into <body>, shown only ≤899.98px. Navy to match the top bar;
   muted icons, active tab goes full white ("white = active page"). */
#bottom-nav { display: none; }
@media (max-width: 899.98px) {
  #bottom-nav {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 1150;
    display: grid; grid-template-columns: repeat(5, 1fr);
    background: #0f1a2e;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding-bottom: env(safe-area-inset-bottom, 0px);
    box-shadow: 0 -6px 20px -12px rgba(8, 15, 30, 0.6);
  }
  .botnav-tab {
    position: relative;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    gap: 5px; padding: 10px 4px 9px;
    background: none; border: none; cursor: pointer;
    color: rgba(255, 255, 255, 0.55);
    text-decoration: none; font-family: inherit;
    transition: color .14s, background-color .14s, transform .08s;
    -webkit-tap-highlight-color: transparent;
    -webkit-user-select: none; user-select: none;   /* no stray text-selection marks (#17) */
  }
  /* Never underline (the Home <a> was picking up a hover underline, #29). */
  .botnav-tab, .botnav-tab:focus, .botnav-tab:active { text-decoration: none; }
@media (hover: hover) { .botnav-tab:hover { text-decoration: none; } }
  .botnav-tab:focus-visible { outline: none; }
  /* Hover only with a real pointer — never sticks after a tap on touch (#29). */
  @media (hover: hover) {
    .botnav-tab:hover { color: #fff; background: rgba(255, 255, 255, 0.07); }
  }
  /* Press feedback — momentary, doesn't carry to the next page. */
  .botnav-tab:active { color: #fff; background: rgba(255, 255, 255, 0.1); transform: scale(0.93); }
  .botnav-tab.is-active { color: #fff; }

  /* The top-bar action pills now live in the bottom nav — hide them on
     mobile. Keep the settings gear up top so preferences stay reachable. */

  /* Clear the fixed bottom nav (64px + iOS safe area). Scrolling home gets
     extra bottom padding; the app-mode locked topic panel shrinks its
     internal scroll height so the last row clears the bar. Selectors mirror
     the base rules' specificity so these overrides actually win. */
  html body.home-search.app-mode.sticky-always.has-subnav #content,
  html body.home-search.app-mode #content {
    padding-bottom: calc(64px + env(safe-area-inset-bottom, 0px) + 1.1rem);
  }
  body.app-mode.sticky-always.has-subnav:not(.home-search) #content,
  body.app-mode:not(.home-search) #content {
    height: calc(100dvh - var(--nav-h) - var(--subnav-height, 66px) - 64px - env(safe-area-inset-bottom, 0px));
  }

  /* ── Modals + the bottom nav (#3/#6) ───────────────────────────────────
     Center every takeover in the space ABOVE the 60px bottom bar (not hidden
     behind it), and trim the width a touch so tapping the side dismisses. */
  html .takeover-overlay,
  html .all-topics-modal-overlay {
    align-items: center;
    padding-bottom: calc(60px + env(safe-area-inset-bottom, 0px) + 0.85rem);
  }
  /* tlm/td panels self-center via top:50% — lift the center above the nav. */
  html .tlm-panel,
  html .td-panel { top: calc(50% - 34px); }
  /* Narrower cards + height capped to the space above the bar. */
  html .takeover-panel,
  html .all-topics-modal-card,
  html .tlm-panel,
  html .td-panel {
    max-width: 440px;
    width: calc(100% - 2.6rem);
    max-height: calc(100dvh - 60px - env(safe-area-inset-bottom, 0px) - 2.2rem);
  }
}

/* ═══════════════ Mobile top bar — ESPN-style (2026-06-11) ═════════════
   Consistent on EVERY page: [☰ Standard Topic] left-aligned, [🔍] search on
   the right (still handy even though Search is in the bottom nav too). The
   page/topic title is NOT in the top bar — it moves to the sub-header
   identity line below (see the mobile sub-header rules). */
.nav-back { display: none; }
.nav-search-mobile { display: none; }
/* The header page-name panel + the subnav "Related/Featured" lead label are a
   mobile/tabular-only treatment (≥900 keeps topic links in the nav + the title
   in the subnav). Hidden by default; shown inside the ≤899 block. */
.sticky-page-name { display: none; }
/* Inline section tabs in the topic subnav are mobile/tabular-only (≥900 keeps
   the title + related chips). Hidden by default; shown inside the ≤899 block. */
.subnav-tabs { display: none; }
/* The mobile-hero icon + one-sentence description are mobile/tabular-only too
   (desktop keeps the compact identity line). */
.topic-hero-ico { display: none; }
.topic-banner-desc { display: none; }
/* The Related wrapper is transparent by default so its children (lead label +
   chip strip) participate in the desktop legacy subnav grid as if direct
   children; the mobile hero overrides it to a flex row (label + divider + chips). */
.topic-hero-related { display: contents; }
@media (max-width: 899.98px) {
  .nav-back { display: none !important; }   /* retired on mobile */
  /* The old single-search-icon mobile nav (hamburger + brand + a lone search icon,
     actions hidden) is fully retired: 561–899 now uses the SAME single-row icons-
     after-title design as wider screens, and ≤560 uses the two-row grid. So NO
     hamburger/brand order or actions display overrides here — they fought the
     icons-after-title layout and shoved the brand to the far right (#img157). The
     standalone mobile search icon stays hidden at every width now. */
  .sticky-hero-inner .nav-search-mobile { display: none !important; }

  /* (The mobile TOPIC hero — big title + description + scroll-collapse, #92/#93 —
     is being built as a dedicated pass; the topic subnav currently uses the
     legacy title + related-chip strip, with section tabs in the body-tab row.) */

  /* ── About/Terms/Prompt keep the dark→light header page-name panel (#79); only
     TOPIC pages moved the name into the hero above. ───────────────────────── */
  .sticky-hero-inner { position: relative; }
  .sticky-hero-inner .sticky-page-name:not(:empty) {
    order: 3; display: inline-flex; align-items: center; gap: 0.6rem; align-self: stretch;
    flex: 0 1 auto; min-width: 0; max-width: 64vw;
    margin-left: 0; padding: 0 1.5rem;
    background: linear-gradient(180deg, #f7f9fc 0%, #eaf0f8 100%);
    border-left: 1px solid rgba(255, 255, 255, 0.14);
    box-shadow: inset 1px 0 0 rgba(255, 255, 255, 0.55), inset 0 -1px 0 rgba(15, 26, 46, 0.06);
    color: #14213d; font-family: var(--font-display); white-space: nowrap; overflow: hidden;
  }
  .sticky-hero-inner .sticky-page-text {
    min-width: 0; overflow: hidden; text-overflow: ellipsis;
    font-size: 1.15rem; font-weight: 700; letter-spacing: -0.022em; line-height: 1;
  }
  .sticky-hero-inner .sticky-page-name:not(:empty) ~ .nav-search-mobile { display: none; }

  /* HOME keeps the pinned "Featured" lead label + the featured-topic chips. */

  /* Identity-only pages (About / Terms / Prompt Builder) — no chips, no tabs —
     the name is in the header, so the empty subnav band is hidden. The home
     "Home" dropdown picker is NOT empty, so keep it shown (#88). */
  /* ...but NOT the Topics/Trending/Prompts/Hub page-nav bars (revamp829).
     Those are identity-only too, so they matched this rule and got display:none
     on mobile — killing the reveal, which only toggles opacity/visibility. They
     must show on scroll at every width, so exempt .pagenav. */
  #sub-header.is-subnav:not(.pagenav):not(:has(.subnav-topics-inline)):not(:has(.subnav-tabs)):not(:has(.topic-subnav-picker)) { display: none; }
}

/* Search pill — opens the Topics modal with input focused. Mirrors
   the Choose Topics pill's white-on-navy treatment so the two
   read as a paired set (browse vs. search), with the icon cluster
   (Home · Settings) sitting separately to the right. On mobile
   the "Search" text label hides so only the magnify icon remains;
   the button shrinks to match the surrounding icon chips. */

/* Navmenu Settings button — sits in the footer row alongside
   About / Terms / GitHub, with a leading gear icon. */
.navmenu-link-button {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  background: transparent;
  border: none;
  padding: 0;
  font: inherit;
  cursor: pointer;
}
@media (hover: hover) { .navmenu-link-button:hover { color: var(--color-primary); } }
/* === Hamburger Menu ====================================================
   The hamburger lives permanently in the main nav, immediately to the
   left of the brand title. There is no subnav hamburger and no site
   logo image — the menu trigger is the only "pre-title" element. */
.nav-hamburger {
  display: flex;
  width: 24px;
  height: 18px;
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
  flex-direction: column;
  justify-content: space-between;
  flex-shrink: 0;
  opacity: 0.85;
  transition: opacity 0.12s;
}
@media (hover: hover) { .nav-hamburger:hover { opacity: 1; } }
.nav-hamburger span {
  display: block;
  width: 100%;
  height: 2px;
  background: white;
  border-radius: 1px;
}

/* Slide-out nav menu */
.navmenu-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  z-index: 500;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}
.navmenu-overlay.is-open { opacity: 1; pointer-events: auto; }

.navmenu-panel {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 320px;
  max-width: 85vw;
  background: var(--color-bg);
  z-index: 501;
  transform: translateX(-100%);
  transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  flex-direction: column;
  box-shadow: 4px 0 20px rgba(0, 0, 0, 0.15);
  /* The WHOLE drawer scrolls as one (Search + Navigate + Topics together); the
     head pins to the top and the footer to the bottom (see below). */
  overflow-y: auto;
  overscroll-behavior: contain;
}
.navmenu-panel.is-open { transform: translateX(0); }

/* Scrollable middle section — featured topics list flexes to fill the
   remaining height between the fixed top (head/search/prompt) and the
   sticky bottom (View All + footer links), and scrolls when overflowing. */
.navmenu-scroll {
  /* No longer a self-scrolling region — the whole panel scrolls now, so this is
     just the topics block in normal flow. */
  flex: 0 0 auto;
  min-height: 0;
}
/* When the topic list overflows below the visible area, fade the
   bottom-most ~50px of the scroll viewport. Hints that more topics
   exist; disappears once the user has scrolled to the very last
   topic so the final entry stays fully readable. */
.navmenu-scroll.has-overflow-bottom {
  -webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 calc(100% - 56px), rgba(0, 0, 0, 0.2) 100%);
  mask-image: linear-gradient(to bottom, #000 0%, #000 calc(100% - 56px), rgba(0, 0, 0, 0.2) 100%);
}

/* "View All Topics" — balanced-blue link under the Topics list (replaces the old
   Navigate-row button, #img87/88). Same blue family as .navmenu-subtopic-parent. */
.navmenu-viewall {
  display: flex; align-items: center; gap: 0.6rem;
  /* First row under the "Topics" header (#img120). */
  margin: 0.05rem 0.5rem 0.15rem; padding: 0.55rem 0.75rem; border-radius: 8px;
  font-family: var(--font-family); font-size: 0.88rem; font-weight: 650;
  color: #2f4d9e; text-decoration: none; transition: background 0.12s, color 0.12s;
}
.navmenu-viewall svg { flex: none; }
.navmenu-viewall .navmenu-viewall-arrow { margin-left: 1px; transition: transform 0.14s ease; }
@media (hover: hover) {
  .navmenu-viewall:hover { background: #eef2fb; color: #26407f; text-decoration: none; }
  .navmenu-viewall:hover .navmenu-viewall-arrow { transform: translateX(3px); }
}

/* Sticky bottom group — About / Terms / GitHub links. Pinned to the
   bottom of the drawer regardless of featured-topics list length, with
   a discreet light-grey backdrop and a top border for clean separation
   from the scrollable list above. */
.navmenu-footer-sticky {
  flex-shrink: 0;
  background: var(--color-bg-light);
  border-top: 1px solid var(--color-border);
  padding: 0.7rem 1rem;
  /* Pin to the bottom of the drawer while the body scrolls. */
  position: sticky;
  bottom: 0;
}

.navmenu-head {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 1.1rem 1.1rem 1rem;
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
  /* Pin the head (close/brand/home) while the panel body scrolls beneath it. */
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--color-bg);
}
.navmenu-brand {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  text-decoration: none;
  min-width: 0;
  flex: 1 1 auto;
}
@media (hover: hover) { .navmenu-brand:hover { text-decoration: none; } }
.navmenu-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: -0.025em;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  height: 34px;
}
/* Menu head buttons share the same shape, size, and quiet ghost
   styling so they read as a matched pair flanking the brand title.
   The Close (left) carries a muted icon to read as a "dismiss"
   utility; the Home (right) carries a primary-tinted icon to read
   as a quiet "navigate" action — color-only differentiation
   instead of a heavy filled chip. */
.navmenu-close,
.navmenu-home {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg-light, #f3f5f9);
  border: 1px solid #e6e8ec;
  border-radius: 9px;
  cursor: pointer;
  flex-shrink: 0;
  text-decoration: none;
  transition: background 0.14s, border-color 0.14s, color 0.14s, transform 0.06s;
}
/* Home + Settings sit together at the right edge of the menu head,
   with a tighter gap between them than the head's overall gap so
   they read as a paired action cluster. margin-left: auto pushes
   the cluster against the right edge regardless of brand width. */
.navmenu-head-actions {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-left: auto;
}
/* ⓘ button right of the brand title — round, darker-blue tint (#img94). */
.navmenu-info {
  margin-left: auto; flex-shrink: 0;
  width: 30px; height: 30px; display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%; cursor: pointer;
  background: color-mix(in srgb, #26375a 8%, #fff);
  border: 1px solid #d7deea; color: #26375a;
  transition: background 0.14s, border-color 0.14s;
}
@media (hover: hover) { .navmenu-info:hover { background: color-mix(in srgb, #26375a 14%, #fff); border-color: #c2cde0; } }
.navmenu-info[aria-expanded="true"] { background: #26375a; border-color: #26375a; color: #fff; }
/* Mini dropdown under the ⓘ — About / Terms / GitHub (#img94). */
.navmenu-info-pop {
  position: absolute; right: 1rem; top: calc(100% - 8px);
  min-width: 170px; padding: 6px; display: none; z-index: 30;
  background: #fff; border: 1px solid #e3e8f0; border-radius: 12px;
  box-shadow: 0 16px 32px -16px rgba(15, 23, 42, 0.28), 0 4px 10px -6px rgba(15, 23, 42, 0.12);
}
.navmenu-info-pop.is-open { display: block; }
.navmenu-info-pop a {
  display: flex; align-items: center; gap: 9px; padding: 8px 10px; border-radius: 8px;
  font-family: var(--font-family); font-size: 0.85rem; font-weight: 600;
  color: #33415c; text-decoration: none; transition: background 0.12s, color 0.12s;
}
.navmenu-info-pop a svg { flex: none; color: #5a6b86; }
@media (hover: hover) { .navmenu-info-pop a:hover { background: #f4f6fb; color: #26375a; } .navmenu-info-pop a:hover svg { color: #26375a; } }
.navmenu-close { color: var(--color-text-muted, #6b7280); }
.navmenu-home  { color: #2c4467; }
@media (hover: hover) { .navmenu-close:hover {
  background: #eef2f7;
  border-color: #c8d3e3;
  color: var(--color-text, #1e2d44);
} }
@media (hover: hover) { .navmenu-home:hover {
  background: #ebf2fb;
  border-color: #95a8c5;
  color: #1f3251;
  text-decoration: none;
} }
.navmenu-close:active,
.navmenu-home:active { transform: translateY(1px); }
.navmenu-close svg,
.navmenu-home svg { display: block; }

.navmenu-search {
  /* Tight top so the "Search" label sits as close to the bar as the "Navigate"
     label sits to its buttons; bottom matched to the quicklinks so the
     Search→Navigate gap equals the Navigate→Topics gap. */
  padding: 0.35rem 1.25rem 0.5rem;
}
.navmenu-search .search-bar {
  width: 100%;
  height: 42px;
  padding: 0 0.95rem;
  font-size: 0.85rem;
  border: 1px solid var(--color-border);
  background: #fff;
  color: var(--color-text-muted);
  border-radius: 7px;
  font-weight: var(--font-weight-regular);
  gap: 0.55rem;
  display: flex;
  align-items: center;
  cursor: pointer;
  transition: border-color 0.14s, background 0.14s;
}
@media (hover: hover) { .navmenu-search .search-bar:hover {
  border-color: var(--color-primary);
  background: var(--color-bg-light);
} }
.navmenu-search .search-bar-icon { color: var(--color-text-muted); opacity: 0.7; }

/* Quick-jump links between the search bar and the Featured Topics
   list. Text-only — not buttons — so the visual weight stays on
   the search bar above and the topic list below. Stacked one per
   row, left-aligned with the rest of the menu padding. */
.navmenu-quicklinks {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  /* More head-room now that the "Navigate" label above is gone (#img89). */
  padding: 1.1rem 1.25rem 0.5rem;
  align-items: stretch;
}
/* CTA-style menu link — bordered pill that reads as a clear action,
   with a leading subject icon and a trailing arrow indicating
   navigation. Used for "Prompt Builder" and "View All Topics" in
   the expanded menu. Both buttons share the same dimensions: same
   height, same padding, full container width. */
.navmenu-cta {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  box-sizing: border-box;
  min-height: 42px;
  padding: 0.5rem 0.75rem;
  background: var(--color-bg);
  border: 1.5px solid #e1e6ef;
  border-radius: 10px;
  font-family: var(--font-family);
  font-size: 0.85rem;
  font-weight: var(--font-weight-semibold);
  color: #1e2d44;
  text-decoration: none;
  text-align: left;
  cursor: pointer;
  letter-spacing: -0.003em;
  transition: border-color 0.14s, background 0.14s, color 0.14s, transform 0.06s;
}
.navmenu-cta-icon {
  flex-shrink: 0;
  color: #2c4467;
  display: inline-flex;
  width: 18px;
  height: 18px;
}
.navmenu-cta-icon svg { width: 100%; height: 100%; display: block; }
.navmenu-cta-label {
  flex: 1;
  min-width: 0;
}
.navmenu-cta-arrow {
  flex-shrink: 0;
  color: var(--color-text-muted);
  transition: transform 0.14s, color 0.14s;
}
@media (hover: hover) {
  .navmenu-cta:hover {
    border-color: #95a8c5;
    background: #f5f8fd;
    color: var(--color-primary-dark);
    text-decoration: none;  /* Prompt Builder is an <a> — kill the global a:hover underline */
  }
  .navmenu-cta:hover .navmenu-cta-arrow {
    color: var(--color-primary);
    transform: translateX(2px);
  }
}
.navmenu-cta:active { transform: translateY(1px); }
.navmenu-footer-links {
  display: flex;
  gap: 0.3rem;
  padding: 0;
  flex-wrap: nowrap;
  justify-content: center;
  align-items: center;
}
.navmenu-footer-sticky .navmenu-footer-links .navmenu-link {
  background: transparent;
  border: 1px solid transparent;
  color: var(--color-text-muted);
  font-size: 0.74rem;
  padding: 0.35rem 0.4rem;
  gap: 0.3rem;
  flex: 1 1 0;
  min-width: 0;
  justify-content: center;
  white-space: nowrap;
}
@media (hover: hover) { .navmenu-footer-sticky .navmenu-footer-links .navmenu-link:hover {
  background: #fff;
  border-color: var(--color-border);
  color: var(--color-text);
} }
.navmenu-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: 5px;
  font-size: 0.82rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text);
  text-decoration: none;
  transition: border-color 0.12s, background 0.12s;
}
@media (hover: hover) { .navmenu-link:hover { border-color: var(--color-primary); background: var(--color-bg-light); text-decoration: none; } }
.navmenu-featured-label {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-primary);
  text-transform: none;
  letter-spacing: -0.015em;
  padding: 0.9rem 1.25rem 0.5rem;
}

/* === Touch devices: kill sticky :hover ================================
   iOS/Android keep :hover applied to a tapped element until the next tap
   elsewhere, so after navigating, the element in the same screen spot on the
   NEXT page reads as "held down." Neutralise hover visuals where hover isn't a
   real input; tap feedback still comes from :active. */
@media (hover: none) {
  @media (hover: hover) { .navmenu-topic-link:hover, .navmenu-subtopic-link:hover, .navmenu-topic-summary:hover, .navmenu-quicklink:hover, .navmenu-link:hover, .ti-accordion-summary:hover, .ti-item:hover, .ti-model-trigger:hover, .ti-act:hover, .at-sub:hover, .at-acc-flat:hover, .news-card:hover, .news-action:hover, .news-ai-opt:hover, .trend-card-trigger:hover, .trend-ai-opt:hover, .sidebar-shortcut:hover, .trending-topics-viewall:hover {
    background: transparent;
  } }
  /* Bordered rows also revert their hover border / shadow. */
  @media (hover: hover) { .ti-item:hover { border-color: transparent; } }
  @media (hover: hover) { .at-acc-flat:hover { border-color: #e2e6ee; box-shadow: none; } }
}
/* The whole panel scrolls now (the head pins instead), so the "Topics" label
   scrolls with its list — no longer sticky (would collide with the pinned head). */
.navmenu-scroll > .navmenu-featured-label {
  position: static;
}

.navmenu-topics {
  display: flex;
  flex-direction: column;
  padding: 0 0.5rem;
}
.navmenu-topic-link {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.55rem 0.75rem;
  font-size: 0.88rem;
  font-weight: var(--font-weight-medium);
  color: var(--color-text);
  text-decoration: none;
  border-radius: 4px;
  transition: background 0.1s;
}
@media (hover: hover) { .navmenu-topic-link:hover { background: var(--color-bg-light); text-decoration: none; } }
.navmenu-topic-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  color: var(--color-primary, #385c95);
}
.navmenu-topic-icon svg {
  width: 18px;
  height: 18px;
  display: block;
}
/* Topic accordion: the summary toggles subtopics; the "All {name}" link inside
   navigates to the parent topic. */
.navmenu-topic-summary {
  display: flex; align-items: center; gap: 0.65rem;
  padding: 0.55rem 0.75rem; cursor: pointer; list-style: none; user-select: none;
  font-size: 0.88rem; font-weight: var(--font-weight-medium); color: var(--color-text);
  border-radius: 4px; transition: background 0.1s;
}
.navmenu-topic-summary::-webkit-details-marker { display: none; }
@media (hover: hover) { .navmenu-topic-summary:hover { background: var(--color-bg-light); } }
.navmenu-topic-summary .navmenu-topic-name { flex: 1 1 auto; min-width: 0; }
.navmenu-topic-chev { flex: none; color: #9aa5b8; transition: transform 0.2s ease; }
.navmenu-topic-chev svg { display: block; }
.navmenu-topic-acc[open] > .navmenu-topic-summary .navmenu-topic-chev { transform: rotate(180deg); color: var(--color-primary, #385c95); }
/* Open accordion gets a soft tint so its subtopics read as one grouped block
   (no harsh guide line). Subtopics align just under the parent name. */
.navmenu-topic-acc[open] { background: #f6f8fc; border-radius: 8px; }
.navmenu-subtopics {
  display: flex; flex-direction: column;
  margin: 0; padding: 0.05rem 0.5rem 0.4rem 1.9rem;
}
.navmenu-subtopic-link {
  /* 0.85rem — a touch bigger when the accordion is expanded, still under the
     parent row's 0.88rem (#img86). */
  padding: 0.4rem 0.6rem; font-size: 0.85rem; font-weight: 500;
  color: #4a5568; text-decoration: none; border-radius: 4px; transition: background 0.1s, color 0.1s;
}
@media (hover: hover) { .navmenu-subtopic-link:hover { background: color-mix(in srgb, var(--color-primary) 8%, #fff); color: var(--color-primary); text-decoration: none; } }
/* Prominent parent link at the top of the nested list — accent colour, with a
   chevron so it reads clearly as a navigable link (not just a header). */
.navmenu-subtopic-parent { display: flex; align-items: center; gap: 4px; color: #2f4d9e; font-weight: 700; }
@media (hover: hover) { .navmenu-subtopic-parent:hover { color: #26407f; background: #eef2fb; } }
.navmenu-subtopic-arrow { flex: none; transition: transform .14s; }
@media (hover: hover) { .navmenu-subtopic-parent:hover .navmenu-subtopic-arrow { transform: translateX(2px); } }

/* ====================================================================
   Sticky sub-nav (topic + custom pages only)
   Sits directly below the main nav as a second fixed band.
   Contains the topic title + tabs.
   ==================================================================== */
#sub-header.is-subnav {
  position: fixed;
  top: var(--nav-h);
  left: 0;
  right: 0;
  z-index: 99;
  /* Unified subnav surface: the title row and the related-topics
     chip strip share this same fill, so the two read as one
     cohesive identity band. A single bordering/shadow at the
     bottom is the only hard separator between the subnav and
     the body content below it. Inverted hierarchy (#2): the identity/subtopic
     band is now the DARKER fill; the tab control below it goes lighter. */
  background: #e7ecf3;
  border-bottom: 1px solid #cdd2d9;
  box-shadow: 0 2px 8px rgba(15, 26, 46, 0.06);
}

/* === Home subnav (desktop) ===
   Lives in document flow below the hero so it's visible by default.
   Becomes sticky once scrolled past, then transitions from top: 0 to
   top: 56px when the main sticky nav reveals. */

/* Apply the same inner topic-banner overrides as the fixed subnav.
   Horizontal padding matches main nav + topic-layout at every
   breakpoint so all three left edges line up. */
#sub-header.is-home-subnav .topic-banner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1rem 2rem 0.95rem;
  border-bottom: none;
  display: flex;
  align-items: center;
  min-height: 56px;
}

#sub-header.is-home-subnav .topic-banner-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex: 1;
  min-width: 0;
}
#sub-header.is-home-subnav .topic-banner-titlegroup {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

#sub-header.is-home-subnav .topic-banner-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  line-height: 1.15;
  letter-spacing: -0.026em;
  font-weight: 300;
}

#sub-header.is-home-subnav .topic-banner-accent {
  height: 26px;
  width: 3.5px;
}

#sub-header.is-home-subnav .topic-banner-tabs {
  gap: 1.25rem;
  align-items: center;
}

#sub-header.is-home-subnav .topic-banner-tabs .tab-pill {
  font-size: 0.85rem;
  padding: 0.4rem 0 0.4rem;
}

#sub-header.is-subnav .topic-banner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1rem 2rem 0.95rem;
  border-bottom: none;
  display: flex;
  align-items: center;
  min-height: 56px;
  overflow: hidden;
}

#sub-header.is-subnav .topic-banner-row {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex: 1;
  min-width: 0;
}
#sub-header.is-subnav .topic-banner-titlegroup {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}
#sub-header.is-subnav .topic-banner-titleinner {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
}

#sub-header.is-subnav .topic-banner-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 600;
}
/* Desktop subnav (#31/#32): carry the mobile ESPN look up here — small bold
   topic name (scaled a touch larger than mobile), no "TOPIC" badge, and a
   trimmed band height (it was ~66px / 21px title — way too tall). */
@media (min-width: 900px) {
  #sub-header.is-subnav .topic-banner-titleinner .topic-banner-title { font-size: 1.2rem !important; font-weight: 700; line-height: 1.15; }
  #sub-header.is-subnav .topic-banner-kind { display: none; }
  #sub-header.is-subnav .topic-banner { padding-top: 0.5rem; padding-bottom: 0.5rem; min-height: 0; }
}

/* Custom-search title: small uppercase "SEARCH" tag inline with the
   query term, both vertically centered with the search icon to its
   left. Reads as one cohesive label-value pair instead of a
   stacked two-line block. */
.topic-banner-title.topic-banner-title-search {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 0;
  line-height: 1.15;
  flex-wrap: nowrap;
}
.topic-banner-title-prefix {
  font-family: var(--font-family);
  font-weight: 700;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.11em;
  color: var(--color-text-muted);
  flex-shrink: 0;
  line-height: 1;
  padding: 0.18rem 0.5rem;
  background: rgba(15, 26, 46, 0.06);
  border-radius: 999px;
}
.topic-banner-title-term {
  font-family: var(--font-display);
  font-weight: 700;
  color: #1e2d44;
  font-size: 1.4rem;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  letter-spacing: -0.024em;
  line-height: 1.15;
}
@media (max-width: 899.98px) {
  .topic-banner-title-term { font-size: 1.05rem; }
  .topic-banner-title-prefix { font-size: 0.62rem; padding: 0.14rem 0.4rem; }
  .topic-banner-title.topic-banner-title-search { gap: 0.5rem; }
}

#sub-header.is-subnav .topic-banner-accent {
  height: 26px;
  width: 3.5px;
}

/* === Custom-search subnav — editable search field display ========
   Compact field display: magnify icon, SEARCH eyebrow, the term,
   Edit chip. Sized to match the rest of the subnav heights, not
   to dominate it. Click anywhere reopens the Topics modal
   pre-filled with the current term. */
.custom-search-banner .topic-banner-row {
  padding-top: 0.35rem;
  padding-bottom: 0.35rem;
}
.custom-search-display {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  max-width: 560px;
  padding: 0.38rem 0.45rem 0.38rem 0.65rem;
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  cursor: text;
  font-family: var(--font-family);
  text-align: left;
  transition: border-color 0.14s, box-shadow 0.14s, background 0.14s;
  color: #1e2d44;
}
.custom-search-display:focus-visible {
  border-color: #2c4467;
  box-shadow: 0 1px 6px rgba(28, 58, 107, 0.06);
  outline: none;
}
@media (hover: hover) { .custom-search-display:hover {
  border-color: #2c4467;
  box-shadow: 0 1px 6px rgba(28, 58, 107, 0.06);
  outline: none;
} }
.custom-search-display-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #2c4467;
  flex-shrink: 0;
}
.custom-search-display-icon svg { width: 14px; height: 14px; }
.custom-search-display-label {
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #7c8696;
  flex-shrink: 0;
  padding-right: 0.45rem;
  border-right: 1px solid #e2e6ee;
}
.custom-search-display-term {
  flex: 1 1 auto;
  min-width: 0;
  font-family: var(--font-display);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: #0f1a2e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.custom-search-display-edit {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  padding: 0.22rem 0.5rem;
  background: #f3f5f9;
  border-radius: 5px;
  font-size: 0.68rem;
  font-weight: 600;
  color: #2c4467;
  flex-shrink: 0;
  transition: background 0.14s, color 0.14s;
}
.custom-search-display-edit svg { width: 11px; height: 11px; }
@media (hover: hover) { .custom-search-display:hover .custom-search-display-edit {
  background: #e6ecf5;
  color: #1c3a6b;
} }
@media (max-width: 640px) {
  .custom-search-display { gap: 0.45rem; padding: 0.32rem 0.4rem 0.32rem 0.55rem; }
  .custom-search-display-label { display: none; }
  .custom-search-display-term { font-size: 0.88rem; }
  .custom-search-display-edit span { display: none; }
  .custom-search-display-edit { padding: 0.3rem; }
}

/* === Topic Intelligence accordions ================================
   Sectioned, collapsible UI for the Topic Intelligence panel.
   Each <details> is a section (Web Sources / Discover / Learn /
   Analyze / More) with an icon, label, descriptive blurb, and
   chevron. Open state expands the body containing the list of
   items below — Web Sources rows are external links, AI action
   rows are buttons that toggle into multi-select. */
.ti-accordions {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  margin: 0;
  padding: 0;
}
.ti-accordion {
  --ti-accent: #5d6b7e;
  background: #ffffff;
  border: 1px solid #e2e6ee;
  border-radius: 10px;
  overflow: hidden;
  transition: border-color 0.18s, box-shadow 0.18s;
}
.ti-accordion[open] {
  border-color: color-mix(in srgb, var(--ti-accent) 38%, #e2e6ee);
  box-shadow: 0 2px 10px rgba(15, 26, 46, 0.04);
}
/* Two-row grid: row 1 has icon + section title + chev all in
   line; row 2 puts the blurb in the title column so the
   description wraps under the title text (not under the icon).
   Icon and title share the same baseline row — no more icon
   floating mid-summary. */
.ti-accordion-summary {
  display: grid;
  grid-template-columns: auto 1fr auto;
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 0.4rem;
  row-gap: 0.35rem;
  padding: 0.7rem 0.85rem;
  cursor: pointer;
  list-style: none;
  user-select: none;
  transition: background 0.14s;
}
.ti-accordion-summary::-webkit-details-marker { display: none; }
@media (hover: hover) { .ti-accordion-summary:hover {
  background: color-mix(in srgb, var(--ti-accent) 4%, #ffffff);
} }
.ti-accordion-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  color: var(--ti-accent);
  flex-shrink: 0;
  grid-column: 1;
  grid-row: 1;
  /* Optical nudge: Title-Case glyphs sit slightly high in their line
     box, so a geometrically-centered icon reads as floating. Drop the
     icon 1px to align with the title's visual center. */
  transform: translateY(1px);
}
.ti-accordion-icon svg { width: 19px; height: 19px; stroke-width: 2; }
.ti-accordion-title {
  font-family: var(--font-family);
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: -0.006em;
  line-height: 1.2;
  color: #0f1a2e;
  grid-column: 2;
  grid-row: 1;
}
/* Blurb spans the full card width — left-aligned to the icon
   column, not indented under the title. */
.ti-accordion-blurb {
  font-size: 0.74rem;
  line-height: 1.35;
  color: #8390a3;
  font-weight: 400;
  /* Stop before the chevron column (col 3) so wrapped blurb text never runs
     under the chevron in a narrow sidebar. */
  grid-column: 1 / 3;
  grid-row: 2;
}
/* Chev spans both grid rows so it vertically centers across the
   whole summary (icon+title row + blurb row), not just the title
   row. No background — just the glyph in muted grey, picking up
   the section accent on hover and when expanded. */
.ti-accordion-chev {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #94a0b3;
  transition: transform 0.2s ease, color 0.14s;
  flex-shrink: 0;
  grid-column: 3;
  grid-row: 1 / -1;
}
.ti-accordion-chev svg { width: 20px; height: 20px; }
@media (hover: hover) { .ti-accordion-summary:hover .ti-accordion-chev { color: var(--ti-accent); } }
.ti-accordion[open] .ti-accordion-chev { color: var(--ti-accent); }
.ti-accordion[open] .ti-accordion-chev {
  transform: rotate(180deg);
  color: var(--ti-accent);
}
.ti-accordion-body {
  padding: 0.4rem 0.55rem 0.7rem;
  border-top: 1px solid color-mix(in srgb, var(--ti-accent) 16%, #eef0f5);
  background: color-mix(in srgb, var(--ti-accent) 2.5%, #ffffff);
}

/* AI Intelligence lenses use the same boxed accordion style as Web Sources
   (icon tile + title + blurb), single column within their own column. */
/* Standalone Web Sources section spacing. */
/* Web Sources header: match News Feed / AI Intelligence (no accent bar). */
/* No top margin so it aligns with the AI Intelligence column beside it. */
.websources-section { margin-top: 0; }
.websources-section .sidebar-card-title::before { display: none !important; }
/* Accent bar is hidden, so drop the padding it reserved — flush-left header. */
.websources-section .sidebar-card-title { padding-left: 0; }
.ti-accordions-websources { margin-top: 2px; }

.ti-item-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}
.ti-item-row { margin: 0; padding: 0; min-width: 0; }
.ti-source-groups {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  /* Drop the first eyebrow down from the accordion header above so it
     doesn't ride against the summary divider. */
  padding-top: 0.4rem;
}
/* Web Source rows are secondary links — tighten their vertical rhythm so
   listings and sections sit closer together than the AI shortcut rows. */
.ti-source-groups .ti-item { padding-top: 0.22rem; padding-bottom: 0.22rem; }
.ti-source-groups .ti-item-text { gap: 0.05rem; }
/* Subgroup eyebrow — small uppercase label followed by a hairline rule
   that fills the row, so each cluster (Search / Social / Audio & video
   / Writing) reads as a tidy section divider, matching the hairline-
   separated listings elsewhere on the site. */
.ti-subhead {
  list-style: none;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0;
  padding: 0 0.6rem 0.35rem;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #8a96ad;
  white-space: nowrap;
}
.ti-subhead::after {
  content: "";
  flex: 1;
  height: 1px;
  background: #e6e9ef;
}
.ti-item {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  width: 100%;
  padding: 0.4rem 0.6rem;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  text-align: left;
  font-family: var(--font-family);
  color: var(--color-text);
  cursor: pointer;
  text-decoration: none;
  transition: background 0.14s, border-color 0.14s;
}
@media (hover: hover) { .ti-item:hover {
  background: #ffffff;
  border-color: color-mix(in srgb, var(--ti-accent) 24%, #e2e6ee);
  text-decoration: none;
} }
.ti-item-text {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
  flex: 1;
}
.ti-item-name {
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: -0.006em;
  color: #1a2235;
  line-height: 1.25;
}
.ti-item-desc {
  font-size: 0.72rem;
  line-height: 1.35;
  color: #7d8696;
  font-weight: 400;
}
/* Web Source link rows — no marker slot, title + desc stack. */
.ti-item-link {
  flex-direction: column;
  gap: 0.1rem;
}
/* Web Source rows sit a touch smaller than AI shortcut rows — they're
   secondary "open external search" links, not the primary prompts. */
.ti-item-link .ti-item-name { font-size: 0.76rem; }

/* AI shortcut row marker — compact checkbox that fills in on select. */
.ti-item-marker {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  border-radius: 4px;
  border: 1.5px solid #c5cdd9;
  background: #ffffff;
  flex-shrink: 0;
  margin-top: 0.12rem;
  transition: background 0.14s, border-color 0.14s;
}
.ti-item-marker-check {
  position: absolute;
  inset: 0;
  margin: auto;
  width: 9px;
  height: 9px;
  color: #ffffff;
  opacity: 0;
  transition: opacity 0.12s;
}
.ti-item-shortcut.is-multi-selected .ti-item-marker {
  background: var(--ti-accent);
  border-color: var(--ti-accent);
}
.ti-item-shortcut.is-multi-selected .ti-item-marker-check { opacity: 1; }
.ti-item-shortcut.is-multi-selected {
  background: color-mix(in srgb, var(--ti-accent) 7%, #ffffff);
  border-color: color-mix(in srgb, var(--ti-accent) 35%, #e2e6ee);
}

/* === AI shortcut → model → Submit/Review dropdown ====================
   Click a shortcut to reveal a model list; click a model to reveal its
   Submit / Review actions. Two nested grid-rows expansions. */
.ti-shortcut { position: relative; }
.ti-shortcut-trigger { align-items: center; }
.ti-shortcut-chev { flex: 0 0 auto; align-self: center; color: #b8c2d2; transition: transform 0.2s ease, color 0.14s; }
@media (hover: hover) { .ti-shortcut-trigger:hover .ti-shortcut-chev { color: var(--ti-accent, #3261a0); } }
/* Expanded shortcut: NO nested card/border (the group accordion is already a
   bordered card — a second border inside read as heavy "card-in-card"). Just a
   soft accent-tinted fill + a left accent bar in the group's colour, so the
   whole expansion reads as one quiet block hanging off its group. */
/* Open shortcut: quiet neutral fill, NO colored left accent bar (the old
   group-accent stripe + eyebrow read as gimmicky). */
.ti-shortcut.is-open {
  background: #f6f8fb;
  border-radius: 10px;
  box-shadow: none;
}
.ti-shortcut.is-open > .ti-shortcut-trigger { background: transparent; border-color: transparent; }
.ti-shortcut.is-open .ti-shortcut-chev { transform: rotate(180deg); color: var(--color-text-light); }
.ti-shortcut-panel { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows 0.26s ease, opacity 0.2s ease; }
.ti-shortcut.is-open .ti-shortcut-panel { grid-template-rows: 1fr; opacity: 1; }
.ti-shortcut-panel-inner {
  overflow: hidden; min-height: 0;
  margin: 0;
  padding: 0.3rem 0.7rem 0.7rem;
}
/* Per-shortcut submission chooser (consistent with the AI Intelligence
   component + insight modal): Direct Submit / Review Prompt + leaving-site. */
.ti-explore { display: grid; gap: 6px; }
.ti-explore-opt { display: flex; align-items: center; gap: 11px; width: 100%; text-align: left; padding: 10px 12px; border: 1px solid var(--color-surface-border); border-radius: 10px; background: #fff; cursor: pointer; font-family: var(--font-family); transition: border-color .14s, background .14s; }
@media (hover: hover) { .ti-explore-opt:hover { border-color: var(--color-primary); background: #f7f9fc; } }
.ti-explore-ic { flex: none; width: 34px; height: 34px; display: inline-flex; align-items: center; justify-content: center; border-radius: 9px; background: color-mix(in srgb, var(--color-primary) 9%, #fff); color: var(--color-primary); }
.ti-explore-tx { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1 1 auto; }
.ti-explore-name { font-size: 0.85rem; font-weight: 600; color: var(--color-text); }
.ti-explore-sub { font-size: 0.74rem; color: var(--color-text-muted); }
.ti-explore-go { flex: none; color: var(--color-text-light); display: inline-flex; }
.ti-leave-back { display: inline-flex; align-items: center; gap: 5px; padding: 0 0 8px; border: none; background: none; cursor: pointer; font-family: var(--font-family); font-size: 0.78rem; font-weight: 600; color: var(--color-text-muted); }
@media (hover: hover) { .ti-leave-back:hover { color: var(--color-primary); } }
.ti-leave-card { padding: 13px 14px 14px; border: 1px solid var(--color-surface-border); border-radius: 11px; background: #fff; }
.ti-leave-title { margin: 0 0 5px; font-size: 0.88rem; font-weight: 700; color: var(--color-text); }
.ti-leave-body { margin: 0 0 12px; font-size: 0.79rem; line-height: 1.45; color: var(--color-text-muted); }
.ti-leave-go { display: inline-flex; align-items: center; gap: 6px; padding: 9px 16px; border: none; border-radius: 999px; background: var(--color-primary); color: #fff; cursor: pointer; font-family: var(--font-family); font-size: 0.82rem; font-weight: 600; transition: background .14s; }
@media (hover: hover) { .ti-leave-go:hover { background: color-mix(in srgb, var(--color-primary) 88%, #000); } }
.ti-leave-go svg { stroke: #fff; }
.ti-shortcut-modelslabel { font-size: 0.56rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #97a1b3; padding: 0.2rem 0 0.34rem 0.1rem; }
/* Group AI overview — fills the accordion body for Discover/Learn/Analyze/
   Topic-Insights on home + topic pages (custom pages keep shortcut rows). */
/* Header: AI eyebrow + freshness on the left, "Run full overview" on the right,
   separated from the sections by a hairline. */

/* Each section is its own card with a navy accent rail. */
/* Briefing sections as nested mini-accordions: click the lens, then expand the
   piece you want (Beginner's Guide, Glossary, Trends to Watch…). */
@keyframes tiOvFade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
/* Key takeaways: clean hanging-arrow lines, no boxes. */
/* Explore in chat → subtle ghost chip aligned to the section. */
/* Loading skeleton shimmer */
@keyframes ti-skel-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
/* Model rows read as sub-options: lighter than the shortcut title above. */
.ti-shortcut-panel-inner .ti-model-trigger { font-weight: 500; }
.ti-model + .ti-model { margin-top: 0; }
.ti-model-trigger {
  display: flex; align-items: center; justify-content: space-between; width: 100%;
  padding: 0.28rem 0.55rem; border: none; border-radius: 8px; background: transparent;
  font-family: var(--font-family); font-size: 0.82rem; font-weight: 600; color: #2c3a52; cursor: pointer;
  transition: background 0.12s;
}
.ti-model.is-open .ti-model-trigger { background: #eef2f9; }
@media (hover: hover) { .ti-model-trigger:hover { background: #eef2f9; } }
.ti-model-chev { flex: none; color: #b8c2d2; transition: transform 0.2s ease; }
.ti-model-chev svg { display: block; }
.ti-model.is-open .ti-model-chev { transform: rotate(180deg); color: var(--ti-accent, #3261a0); }
.ti-model-actions { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.22s ease; }
.ti-model.is-open .ti-model-actions { grid-template-rows: 1fr; }
.ti-model-actions-inner { overflow: hidden; min-height: 0; display: flex; flex-direction: column; gap: 0.1rem; padding: 0.2rem 0 0.3rem 0.55rem; }
/* The inner's vertical padding doesn't collapse with the 0fr grid track, so a
   closed model still reserves ~8px — enough for the copied-note's top edge to
   peek through. Zero the vertical padding while collapsed so it's truly hidden. */
.ti-model:not(.is-open) .ti-model-actions-inner { padding-top: 0; padding-bottom: 0; }
.ti-act {
  display: flex; align-items: center; gap: 0.45rem; width: 100%; text-align: left;
  padding: 0.42rem 0.55rem; border: none; border-radius: 7px; background: transparent;
  font-family: var(--font-family); font-size: 0.8rem; font-weight: 600; color: #3a4a64; cursor: pointer;
  transition: background 0.12s, color 0.12s;
}
.ti-act svg { flex: none; }
.ti-act-submit { color: #2f7a55; }
@media (hover: hover) { .ti-act:hover { background: #f1f5fc; } }
@media (hover: hover) { .ti-act-submit:hover { color: #1f8f6b; } }
@media (hover: hover) { .ti-act-review:hover { color: #1e2d44; } }

/* Discreet "prompt copied" note shown above the Submit / Review actions
   once a model is expanded (the prompt is copied to the clipboard at that
   moment). Also reused in the Review & Submit modal after submit. */
.pm-copied-note { padding: 0.2rem 0; font-size: 0.78rem; text-align: center; color: #6b7790; }

/* Multi-select is retired — never show its submit bar. */
.shortcuts-multi-submit-wrap { display: none !important; }

@media (max-width: 640px) {
  .ti-accordion-summary { padding: 0.65rem 0.8rem; column-gap: 0.4rem; row-gap: 0.3rem; }
  .ti-accordion-icon { width: 20px; height: 20px; }
  .ti-accordion-icon svg { width: 19px; height: 19px; }
  .ti-accordion-title { font-size: 0.9rem; }
  .ti-accordion-blurb { font-size: 0.72rem; }
  .ti-accordion-body { padding: 0.35rem 0.45rem 0.65rem; }
  .ti-item { padding: 0.4rem 0.55rem; }
  .ti-item-name { font-size: 0.82rem; }
  .ti-item-desc { font-size: 0.7rem; }
}

/* === Custom-search page in-page header =============================
   Replaces the subnav entirely on custom-search pages. The header
   sits at the top of the topic-layout with a title + intro
   sentence, then a search bar that becomes sticky as the user
   scrolls — keeps search reachable without permanently consuming
   the fixed-nav vertical space. */
.topic-layout.is-custom {
  /* Override the app-mode grid constraints — custom pages need to
     scroll the whole page so position: sticky works on the search
     bar. Resets max-height + overflow that app-mode applies to
     the layout panel. */
  height: auto;
  max-height: none;
  overflow: visible;
  display: block;
  padding-bottom: 4rem;
}
/* Custom page sections don't need internal scroll — the page
   itself scrolls. Drop the flex:1 + overflow-y:auto that the
   shortcuts wrap uses on topic pages. */
.topic-layout.is-custom > .layout-section,
.topic-layout.is-custom .shortcuts-scroll-wrap {
  flex: none;
  min-height: 0;
  overflow: visible;
  display: block;
  padding-top: 0;
  padding-right: 0;
  padding-bottom: 0;
}
.topic-layout.is-custom .shortcuts-sidebar {
  height: auto;
  overflow: visible;
}
/* At rest: a tight stacked header — page title + intro. It scrolls
   away; the sticky block below (search bar + Topic Intelligence /
   Covering context) pins under the nav and collapses to a compact
   subnav, all transitioning together. */
.custom-search-head {
  margin: 0 0 0.5rem;
  padding-top: 0.35rem;
}
.custom-search-page-title {
  margin: 0 0 0.3rem;
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: -0.022em;
  line-height: 1.15;
  color: #0f1a2e;
}
.custom-search-page-intro {
  margin: 0;
  max-width: 640px;
  font-size: 0.92rem;
  line-height: 1.45;
  color: #4a5568;
  font-weight: 400;
}
/* The whole block (search bar + TI/covering) is one sticky unit so
   they pin and re-format together. At rest it's flat on the page; once
   pinned it becomes a full-bleed tinted bar (edge to edge under the
   nav) with a clear shadow so it reads as a distinct subnav, not a
   white box lost in white content.
   --bleed = distance from the content column to the viewport edge, so
   negative margins of that size make the bar span full width while the
   matching padding keeps the inner content aligned to the page. */
.custom-search-sticky {
  --bleed: max(32px, calc((100vw - 1440px) / 2 + 32px));
  position: sticky;
  top: var(--nav-h);
  z-index: 20;
  background: transparent;
  margin: 0 0 1.25rem;
  border-bottom: 1px solid transparent;
  transition: background-color 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease;
}
.custom-search-sticky.is-stuck {
  margin-left: calc(-1 * var(--bleed));
  margin-right: calc(-1 * var(--bleed));
  padding: 0.2rem var(--bleed) 0.7rem;
  background: #eef1f6;
  border-bottom-color: #ccd3df;
  box-shadow: 0 8px 18px -5px rgba(15, 26, 46, 0.18);
}
/* Content column gutter is 16px at <=899.98px (matches #content padding). */
@media (max-width: 899.98px) {
  .custom-search-sticky { --bleed: 16px; }
}
.custom-search-page-bar {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.5rem 0 0.45rem;
}
.custom-search-bar-title {
  display: none;
  flex: 0 0 auto;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: #0f1a2e;
  white-space: nowrap;
}
.custom-search-sticky.is-stuck .custom-search-bar-title { display: block; }
.custom-search-page-bar-input {
  flex: 1 1 auto;
  min-width: 0;
}
/* Just a hairline separator beneath the search bar, sitting above the
   accordions. Desktop only; hidden when the bar is pinned (the stuck
   bar's own bottom border + shadow does the separating then). */
.custom-ti-sep {
  height: 0;
  margin-top: 0.5rem;
  border-top: 1px solid #d6dae2;
}
.custom-search-sticky.is-stuck .custom-ti-sep { display: none; }
@media (max-width: 899.98px) {
  .custom-ti-sep { display: none; }
  .custom-search-page-title { font-size: 1.2rem; }
  .custom-search-page-intro { font-size: 0.9rem; }
  .custom-search-bar-title { font-size: 1rem; }
  /* Stuck on mobile: page title wraps above the input in the bar. */
  .custom-search-sticky.is-stuck .custom-search-page-bar {
    flex-wrap: wrap;
    gap: 0.35rem 0.75rem;
  }
  .custom-search-sticky.is-stuck .custom-search-bar-title { flex-basis: 100%; }
  .custom-search-sticky.is-stuck .custom-search-page-bar-input { flex-basis: 100%; }
}

/* === Custom-search subnav: live search input + autocomplete drop ===
   Replaces the read-only "display" pill with a real <input> that
   updates the page in place as the user types. Dropdown anchors
   to the input and lists matching topics + an "Add as custom
   topic" CTA. */
.custom-search-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  max-width: 640px;
  padding: 0.4rem 0.5rem 0.4rem 0.7rem;
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  transition: border-color 0.14s, box-shadow 0.14s;
}
.custom-search-input-wrap:focus-within {
  border-color: #2c4467;
  box-shadow: 0 1px 8px rgba(28, 58, 107, 0.1);
}
.custom-search-input-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #2c4467;
  flex-shrink: 0;
}
.custom-search-input-icon svg { width: 15px; height: 15px; }
.custom-search-input {
  flex: 1 1 auto;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-family: var(--font-display);
  font-size: 0.98rem;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: #0f1a2e;
  padding: 0.2rem 0;
}
.custom-search-input::placeholder { color: #94a0b3; font-weight: 500; }
.custom-search-clear {
  display: none;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: #6c7589;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.14s, color 0.14s;
}
@media (hover: hover) { .custom-search-clear:hover { background: #eef1f6; color: #1c3a6b; } }

/* Dropdown panel — anchors absolutely below the input wrap, no
   gap so the connected look reads as one component. Floats above
   the page content on a small shadow. */
.custom-search-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  z-index: 50;
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 26, 46, 0.12);
  padding: 0.4rem;
  max-height: 360px;
  overflow-y: auto;
}
.custom-search-dropdown[hidden] { display: none; }
.custom-search-result {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.7rem;
  cursor: pointer;
  border-radius: 6px;
  color: var(--color-text);
  transition: background 0.1s;
}
.custom-search-result.is-highlighted {
  background: #f3f5f9;
}
@media (hover: hover) { .custom-search-result:hover {
  background: #f3f5f9;
} }
.custom-search-result-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 0.95rem;
  font-weight: 600;
  color: #0f1a2e;
}
.custom-search-result-name strong {
  background: rgba(255, 213, 96, 0.55);
  color: #0f1a2e;
  font-weight: 700;
  padding: 0.05em 0.15em;
  border-radius: 3px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}
.custom-search-result-parent {
  font-size: 0.74rem;
  color: var(--color-text-light);
  flex-shrink: 0;
}
.custom-search-result-arrow {
  color: var(--color-text-light);
  opacity: 0.5;
  flex-shrink: 0;
}
.custom-search-empty {
  padding: 0.7rem 0.75rem;
  color: var(--color-text-muted);
  font-size: 0.88rem;
  text-align: center;
}
.custom-search-custom-cta {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.6rem 0.7rem;
  margin-top: 0.35rem;
  border-top: 1px solid #e6e9f0;
  cursor: pointer;
  border-radius: 6px;
  transition: background 0.14s;
}
@media (hover: hover) { .custom-search-custom-cta:hover { background: rgba(74, 124, 201, 0.08); } }
.custom-search-custom-badge {
  background: var(--color-primary);
  color: white;
  font-size: 1rem;
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-weight: 700;
  flex-shrink: 0;
  line-height: 1;
}
.custom-search-custom-text {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
  flex: 1;
}
.custom-search-custom-action {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-primary);
  opacity: 0.9;
}
.custom-search-custom-term {
  font-size: 0.95rem;
  font-weight: 700;
  color: #0f1a2e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
@media (max-width: 640px) {
  .custom-search-input-wrap { padding: 0.35rem 0.45rem 0.35rem 0.6rem; max-width: none; }
  .custom-search-input { font-size: 0.95rem; }
  .custom-search-dropdown { padding: 0.3rem; }
  .custom-search-result-name { font-size: 0.92rem; }
}

