/* Custom instructions textarea */
/* Select-style dropdown for prompt generator fields */

.wiz-field-picker-custom-row {
  display: flex;
  gap: 0.35rem;
  padding: 0.55rem 1.15rem;
  border-top: 1px solid var(--color-border);
  flex-shrink: 0;
