.pb-inline .wiz-action-bar-inner {
  /* Zero the 32px inset so the action buttons align with the cards' left edge —
     the prompts nav-dropdown host uses .pb-inline, not body.pb-action-bar-inline
     (#img423). */
  padding: 0;
  padding-bottom: 0;
}
body.pb-action-bar-inline .wiz-action-bar-spacer {
  display: none;
}
@media (max-width: 640px) {
