}
/* Parent rows in topic picker — clearly clickable */
.wiz-topic-picker-card .search-parent-row {
  cursor: pointer;
}
@media (hover: hover) { .wiz-topic-picker-card .search-parent-row:hover {
  background: #e8eaef;
} }
.wiz-topic-parent-hint {
  margin-left: auto;
  font-size: 0.75rem;
  color: var(--color-text-light);
}
.wiz-topic-result {
  cursor: pointer;
}
.wiz-topic-result.is-selected {
  background: var(--color-accent);
}
.wiz-topic-picker-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.65rem 1rem;
  padding-bottom: calc(0.65rem + env(safe-area-inset-bottom, 0px));
  border-top: 1px solid var(--color-border);
  background: var(--color-bg-light, #f6f7f9);
  position: sticky;
  bottom: 0;
  z-index: 10;
  flex-shrink: 0;
}
.wiz-topic-picker-foot-left {
  justify-content: flex-start;
}
.wiz-topic-picker-count {
  color: var(--color-text-muted);
  font-size: 0.8rem;
}
.wiz-topic-picker-title-block {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}
.wiz-topic-picker-desc {
  font-size: 0.78rem;
  color: var(--color-text-muted);
  font-weight: var(--font-weight-regular);
  margin: 0;
  line-height: 1.35;
}
.wiz-custom-badge-inline {
  display: inline-block;
  margin-left: 0.4rem;
  padding: 0.05rem 0.4rem;
  background: var(--color-accent);
  color: var(--color-text-muted);
  font-size: 0.65rem;
  font-weight: var(--font-weight-medium);
  border-radius: 3px;
