/* Sub-sections render as card blocks — each pick category gets its
   own bordered card with a clear heading, then the field UI inside.
   Matches the Topics modal / Settings modal card pattern so the
   Prompt Builder reads as a related family of pickers. */
.wiz-sub-section {
  background: var(--color-bg);
  border: 1px solid #e6e8ec;
  border-radius: 12px;
  padding: 0.95rem 1.05rem 1rem;
  margin-bottom: 0.85rem;
  box-shadow: 0 1px 2px rgba(15, 26, 46, 0.03);
  transition: border-color 0.14s, box-shadow 0.14s;
}
.wiz-sub-section:last-child { margin-bottom: 0; }
.wiz-sub-section:focus-within {
  border-color: #c8d3e3;
  box-shadow: 0 2px 6px rgba(15, 26, 46, 0.06);
}

.wiz-sub-label {
  display: block;
  font-family: var(--font-display);
  font-size: 1rem;
  color: #1e2d44;
  font-weight: 700;
  letter-spacing: -0.012em;
  margin-bottom: 0.65rem;
  line-height: 1.2;
}
.wiz-sub-label .wiz-optional {
  font-family: var(--font-family);
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--color-text-muted);
  margin-left: 0.35rem;
  letter-spacing: -0.005em;
}

/* On wider viewports, the Style step (which is mostly chip-grid
   pickers) and the Content step lay their card blocks out in a
   responsive 2-column grid for a denser, more "settings-like"
   read. Steps add the class on their root, e.g. .wiz-step-body. */
@media (min-width: 720px) {
  .wiz-step-body.wiz-grid-2 {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.85rem;
  }
  .wiz-step-body.wiz-grid-2 .wiz-sub-section { margin-bottom: 0; }
  /* Full-width card for the Custom Instructions textarea so it
     gets the breathing room it needs. */
  .wiz-step-body.wiz-grid-2 .wiz-sub-section.wiz-sub-section-wide {
    grid-column: 1 / -1;
  }
}

/* Live prompt preview — neutral but with real presence */
.wiz-preview {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  margin-bottom: 1rem;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
}

.wiz-preview-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.6rem 0.95rem;
  background: var(--color-bg-light, #f6f7f9);
  border-bottom: 1px solid var(--color-border);
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: var(--font-weight-bold);
  color: var(--color-text);
  letter-spacing: -0.005em;
}
.wiz-preview-head::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}

.wiz-preview-body {
  padding: 0.85rem 0.95rem;
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--color-text);
  white-space: pre-wrap;
  background: var(--color-bg);
}

.wiz-preview-body.wiz-preview-empty {
  color: var(--color-text-light);
  font-style: italic;
}

/* Footer nav */

.wiz-btn-back,
.wiz-btn-skip,
.wiz-btn-next {
  padding: 0.6rem 1.1rem;
  border-radius: 6px;
  font-size: 0.88rem;
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  font-family: var(--font-family);
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.wiz-btn-back {
  background: transparent;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
}

@media (hover: hover) { .wiz-btn-back:hover:not(:disabled) {
  border-color: var(--color-primary-light);
  color: var(--color-text);
} }

.wiz-btn-back:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.wiz-btn-skip {
  background: transparent;
  color: var(--color-text-muted);
  border: none;
}

@media (hover: hover) { .wiz-btn-skip:hover {
  color: var(--color-text);
} }

.wiz-btn-next {
  background: var(--color-primary);
  color: white;
  border: none;
}

@media (hover: hover) { .wiz-btn-next:hover:not(:disabled) {
  background: var(--color-primary-dark);
} }

.wiz-btn-next:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Review step */
.wiz-review {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.wiz-review-section {
  display: flex;
  flex-direction: column;
}

.wiz-prompt-box {
  background: var(--color-bg-light, #f6f7f9);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  padding: 1rem 1.15rem;
  font-size: 0.92rem;
  line-height: 1.6;
  white-space: pre-wrap;
  margin-bottom: 0.6rem;
  max-height: 320px;
  overflow-y: auto;
}

.wiz-prompt-edit {
  width: 100%;
  min-height: 240px;
  max-height: 420px;
  padding: 1rem 1.15rem;
  background: var(--color-bg);
  color: var(--color-text);
  border: 1.5px solid var(--color-primary);
  border-radius: 4px;
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.6;
  resize: vertical;
  outline: none;
  margin-bottom: 0.6rem;
}

.wiz-review-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.45rem;
}

.wiz-review-actions {
  display: flex;
  gap: 0.35rem;
}

.wiz-btn-inline {
  padding: 0.3rem 0.7rem;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  color: var(--color-text);
  font-size: 0.78rem;
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
@media (hover: hover) { .wiz-btn-inline:hover {
  background: var(--color-accent);
  border-color: var(--color-primary);
  color: var(--color-primary);
} }

.wiz-prompt-reset {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  font-size: 0.78rem;
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
  padding: 0.2rem 0;
}
@media (hover: hover) { .wiz-prompt-reset:hover { color: var(--color-primary); } }

/* Prompt generator: step pills in the sticky subnav */

/* "Preview" action in the prompt-generator subnav — opens the live
   prompt preview modal from anywhere in the wizard. */
@keyframes wiz-subnav-preview-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

/* Live prompt preview modal */
.prompt-preview-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}
.prompt-preview-modal-card {
  position: relative;
  background: var(--color-surface);
  border-radius: 6px;
  width: 100%;
  max-width: 620px;
  max-height: 82vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 25px 60px rgba(15, 23, 42, 0.35);
  animation: modalPop 0.18s ease-out;
}
.prompt-preview-modal-close {
  position: absolute;
  top: 0.6rem;
  right: 0.75rem;
  width: 32px;
  height: 32px;
  background: transparent;
  border: none;
  border-radius: 4px;
  color: var(--color-text-muted);
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
@media (hover: hover) { .prompt-preview-modal-close:hover {
  background: var(--color-bg-light);
  color: var(--color-text);
} }
.prompt-preview-modal-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 1.15rem 0.85rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-bg-light, #f6f7f9);
}
.prompt-preview-modal-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}
.prompt-preview-modal-title {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: var(--font-weight-bold);
  color: var(--color-text);
  letter-spacing: -0.01em;
  margin: 0;
}
.prompt-preview-modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.15rem 1.25rem;
  font-size: 0.92rem;
  line-height: 1.65;
  color: var(--color-text);
  white-space: pre-wrap;
}
.prompt-preview-modal-body.is-empty {
  color: var(--color-text-light);
  font-style: italic;
  text-align: center;
  padding: 2rem 1.25rem;
}
.prompt-preview-modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem 1.15rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-bg-light, #f6f7f9);
}
.prompt-preview-modal-copy {
  padding: 0.45rem 0.9rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 4px;
  font-size: 0.82rem;
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: background 0.15s;
}
@media (hover: hover) { .prompt-preview-modal-copy:hover {
  background: var(--color-primary-dark, var(--color-primary));
} }
.prompt-preview-modal-hint {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}
.wiz-subnav-step.is-complete:not(.active) .wiz-subnav-num {
  background: var(--color-primary);
  color: white;
  border-color: var(--color-primary);
}
.wiz-subnav-step.is-complete:not(.active) {
  color: var(--color-text);
}

.wiz-btn-secondary {
  align-self: flex-start;
  padding: 0.45rem 0.9rem;
  background: white;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  font-size: 0.82rem;
  font-weight: var(--font-weight-medium);
  cursor: pointer;
  font-family: var(--font-family);
}

@media (hover: hover) { .wiz-btn-secondary:hover {
  border-color: var(--color-primary-light);
  color: var(--color-text);
} }

.wiz-model-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.wiz-model-btn {
  padding: 0.65rem 0.5rem;
  border: 2px solid var(--color-border);
  background: white;
  border-radius: 8px;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: var(--font-family);
  color: var(--color-text);
  text-align: center;
  transition: border-color 0.15s, background 0.15s;
}

@media (hover: hover) { .wiz-model-btn:hover {
  border-color: var(--color-primary-light);
} }

.wiz-model-btn.selected {
  border-color: var(--color-primary);
  background: var(--color-accent);
  color: var(--color-primary);
  font-weight: var(--font-weight-semibold);
}

.wiz-model-tag {
  font-size: 0.7em;
  color: var(--color-text-light);
}

.wiz-warning {
  padding: 0.7rem 0.85rem;
  background: #fffbeb;
  border: 1px solid #f6e05e;
  color: #744210;
  border-radius: 6px;
  font-size: 0.82rem;
  line-height: 1.5;
}

.wiz-btn-submit {
  width: 100%;
  padding: 0.95rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: var(--font-weight-bold);
  cursor: pointer;
  font-family: var(--font-family);
  letter-spacing: -0.01em;
  transition: background 0.15s;
}

@media (hover: hover) { .wiz-btn-submit:hover {
  background: var(--color-primary-dark);
} }

.wiz-btn-restart {
  width: 100%;
  padding: 0.7rem;
  background: transparent;
  color: var(--color-text-muted);
  border: none;
  font-size: 0.82rem;
  cursor: pointer;
  font-family: var(--font-family);
  text-decoration: underline;
  text-decoration-color: rgba(113, 128, 150, 0.3);
  text-underline-offset: 3px;
}

@media (hover: hover) { .wiz-btn-restart:hover {
  color: var(--color-primary);
} }

.wiz-disclaimer {
  font-size: 0.72rem;
  color: var(--color-text-light);
  text-align: center;
  line-height: 1.5;
  margin: 0;
}

/* Mobile */
@media (max-width: 640px) {
  .wiz-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .wiz-step-title {
    font-size: 1.1rem;
  }

  .wiz-step-desc {
    font-size: 0.82rem;
    margin-bottom: 0.85rem;
  }

  .wiz-model-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .wiz-btn-back,
  .wiz-btn-skip,
  .wiz-btn-next {
    padding: 0.55rem 0.85rem;
    font-size: 0.82rem;
  }
}

@media (max-width: 400px) {
  .wiz-cards {
    grid-template-columns: 1fr;
  }

  .wiz-model-grid {
    grid-template-columns: 1fr;
  }
}

/* === About Page === */
/* Static pages (About / Terms) — restyled to match the current site language
   (#img90-93/97): the subnav carries the page title, so content opens with a
   lead line; deep-navy display headers; grey pill buttons like the pickers. */
.about-page {
  max-width: 720px;
  padding-top: 0.35rem;
}
.about-lead {
  font-size: 1.02rem;
  color: #33415c;
  line-height: 1.65;
  margin: 0 0 0.6rem;
}
.about-updated {
  font-size: 0.78rem; font-weight: 600; color: var(--color-text-muted);
  margin: 0 0 1.4rem;
}
.about-page > .about-lead:last-of-type { margin-bottom: 1.8rem; }
.about-section {
  margin-bottom: 1.6rem;
  padding-bottom: 1.6rem;
  border-bottom: 1px solid #e9edf3;
}
.about-section:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.about-section h3 {
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
  color: #1a2740;
  letter-spacing: -0.01em;
  margin-bottom: 0.6rem;
}
.about-section p {
  font-size: 0.9rem;
  line-height: 1.7;
  color: #33415c;
  margin: 0 0 0.85rem;
}
.about-section p:last-child { margin-bottom: 0; }
.about-section ul + p,
.about-section p + p { margin-top: 0; }
.about-section ul {
  padding-left: 1.15rem;
  font-size: 0.9rem;
  line-height: 1.7;
  color: #33415c;
  list-style: none;
  margin: 0 0 0.85rem;
}
.about-section li {
  margin-bottom: 0.45rem;
  position: relative;
  padding-left: 0.15rem;
}
.about-section li::before {
  content: '';
  position: absolute;
  left: -1rem;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8fa3c4;
}
.about-section li strong,
.about-section p strong { color: #1a2740; }
.about-section a { color: #1d4ed8; font-weight: 600; text-decoration: none; }
@media (hover: hover) { .about-section a:hover { text-decoration: underline; } }
/* CTA button links (Portfolio, LinkedIn, GitHub) — same grey pill family as the
   topic-picker buttons. */
.about-cta-row {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.75rem;
  flex-wrap: wrap;
}
.about-cta-link {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.5rem;
  padding: 7px 14px;
  background: #eef1f6;
  border: 1px solid #dde3ee;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  color: #26375a !important;
  text-decoration: none !important;
  transition: background 0.13s, border-color 0.13s;
}
@media (hover: hover) { .about-cta-link:hover {
  background: #e3e9f4;
  border-color: #ccd6e8;
  text-decoration: none !important;
} }
.about-cta-row .about-cta-link { margin-top: 0; }
/* Closing note — soft card instead of another plain section. Class doubled so it
   out-ranks .about-section:last-child's padding-bottom reset. */
.about-section.about-disclaimer {
  background: #f7f9fc;
  border: 1px solid #e6ebf3;
  border-radius: 12px;
  padding: 1rem 1.15rem;
}
.about-disclaimer p {
  font-size: 0.86rem;
  color: #4a5a75;
  line-height: 1.65;
}

/* === Not Found === */
.not-found {
  text-align: center;
  padding: 3rem 1rem;
}

.not-found h2 {
  margin-bottom: 0.5rem;
}

/* === Typography === */
body {
  font-weight: var(--font-weight-regular);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  letter-spacing: -0.01em;
}

h1, h2, h3, h4, .section-header h2 {
  font-family: var(--font-display);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.02em;
}

.section-header h2 {
  font-weight: var(--font-weight-semibold);
}

.tab-pill,
.shortcut-name {
  font-weight: var(--font-weight-medium);
}

.tab-pill.active {
  font-weight: var(--font-weight-semibold);
}

.prompt-modal-label,
.search-result-header,
.search-result-section-label {
  font-weight: var(--font-weight-semibold);
}

/* === Enhanced Search Bar (prominent) === */
.search-bar {
  padding: 0.85rem 1.1rem;
  font-size: 0.95rem;
  font-weight: var(--font-weight-medium);
  gap: 0.7rem;
  border-radius: 8px;
  width: 100%;
}

.search-bar-icon {
  font-size: 1.1rem;
  flex-shrink: 0;
  color: var(--color-primary);
}

.search-bar-label {
  flex: 1;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.search-bar-wrapper {
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
}

/* === Prompt Generator extras === */

/* === Topic Banner (with integrated tabs) === */
.topic-banner {
  background: transparent;
  border: none;
  border-bottom: 1px solid rgba(30, 45, 68, 0.12);
  border-radius: 0;
  margin-bottom: 1.5rem;
  padding: 0.25rem 0 1.15rem;
}

.topic-banner-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 1.25rem;
  flex-wrap: wrap;
  row-gap: 0.6rem;
}

/* TP3: subtle vertical divider between title group and tabs */
.topic-banner-row .topic-banner-tabs {
  position: relative;
  padding-left: 1.25rem;
}

.topic-banner-row .topic-banner-tabs::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 22px;
  background: var(--color-border);
}

/* Hide the divider when tabs wrap to a second line (mobile / narrow widths) */
@media (max-width: 640px) {
  .topic-banner-row .topic-banner-tabs {
    padding-left: 0;
  }
  .topic-banner-row .topic-banner-tabs::before {
    display: none;
  }
}

.topic-banner-titlegroup {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  flex: 0 0 auto;
}

.topic-banner-accent {
  width: 4px;
  height: 32px;
  background: var(--color-primary);
  border-radius: 2px;
  flex-shrink: 0;
  align-self: center;
}

.topic-banner-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.025em;
  line-height: 1.1;
  color: var(--color-primary);
  margin: 0;
  word-break: break-word;
}

.topic-banner-tabs {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
  flex-shrink: 0;
  align-items: flex-end;
}

.topic-banner-tabs .tab-pill {
  font-size: 0.9rem;
}

@media (max-width: 768px) {
  .topic-banner {
    padding: 0.15rem 0 0.85rem;
    margin-bottom: 1rem;
  }

  .topic-banner-accent {
    height: 26px;
  }

  .topic-banner-title {
    font-size: 1.4rem;
  }
}

/* === Discover / All Topics modals =========================== */
.all-topics-modal-overlay {
  position: fixed;
  inset: 0;
  /* Match the Search / Trending / Prompt takeovers EXACTLY (same tint + frosted
     blur) so every bottom-nav modal dims the top bar the same way — without the
     blur this overlay left the navy header crisp/bright while the others frosted
     it, which read as "some modals turn the top blue, some white" (#4). */
  background: rgba(15, 26, 46, 0.5);
  backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

/* === Settings modal =================================================
   Layout: header / scrollable body / sticky footer. Each setting
   section sits in its own pale card with a clear title + helper
   line. Footer hosts Reset (left) + Cancel / Save (right). */
/* Two-column body on desktop: Default model (col 1, full height) +
   Reasoning over Custom instructions (col 2). */

/* Scrollable middle region — section cards live here. */

/* Label row — holds the model name + the optional DEFAULT tag on
   the same line above the description, since the stacked card is a
   flex column and the tag would otherwise drop to its own row. */

/* Footer — Reset (left), Cancel / Save (right). Sticks to the
   bottom of the modal card. */
@media (hover: hover) { .settings-modal-btn-secondary:hover:not(:disabled) {
  background: #f3f5f9;
  border-color: #95a8c5;
} }
.settings-modal-btn-primary:active:not(:disabled) { transform: translateY(1px); }

.all-topics-modal-card {
  position: relative;
