/* === All Topics modal (revamped: search-modal-style takeover with
   Intelligence-style accordions) ===================================== */
/* Fixed header with a light separator; the body scrolls under it. */
/* The body is a fixed-height flex column that scrolls — its accordion cards
   must keep their natural height (not shrink to fit), so content overflows and
   scrolls instead of squishing. */
/* Subtopics inside an open accordion. */
.at-subs { display: flex; flex-direction: column; padding-top: 0.1rem; }
.at-sub {
  display: flex; align-items: center; gap: 0.6rem; padding: 0.5rem 0.7rem; border-radius: 7px;
  font-size: 0.85rem; font-weight: 500; color: #4a5568; text-decoration: none;
  transition: background 0.12s, color 0.12s;
}
@media (hover: hover) { .at-sub:hover { background: color-mix(in srgb, var(--ti-accent, #3261a0) 9%, #fff); color: #1e2d44; text-decoration: none; } }
/* Subtopic icon — matches the topic-page picker's small leading glyph (#img307). */
.at-sub-icon { flex: none; display: inline-flex; align-items: center; justify-content: center; color: #64748b; }
.at-sub-icon svg { width: 17px; height: 17px; }
.at-sub-name { flex: 1 1 auto; min-width: 0; }
@media (hover: hover) { .at-sub:hover .at-sub-icon { color: var(--ti-accent, #2f6fe0); } }
/* Prominent parent link at the top of the nested list — accent colour, with a
   trailing arrow so it reads as a (clickable) link to the parent topic page. */
.at-sub-parent { gap: 0.6rem; color: var(--ti-accent, #2f6fe0); font-weight: 700; }
.at-sub-parent .at-sub-icon { color: var(--ti-accent, #2f6fe0); }
@media (hover: hover) { .at-sub-parent:hover { color: var(--ti-accent, #1f5fd0); } }
.at-sub-arrow { flex: none; display: inline-flex; color: currentColor; transition: transform 0.14s; }
.at-sub-arrow svg { display: block; }
@media (hover: hover) { .at-sub-parent:hover .at-sub-arrow { transform: translateX(2px); } }
/* Center the topic icon vertically. These rows have no blurb, so collapse the
   Intelligence 2-row grid (whose empty second row + row-gap pushed the icon and
   title above the row's true center) to a single centered row, and make the
   icon a flush-centered block (drop the optical nudge + inline baseline gap). */
.at-acc .ti-accordion-summary { grid-template-rows: auto; row-gap: 0; align-items: center; }
.at-acc .ti-accordion-icon { transform: none; align-self: center; }
.at-acc .ti-accordion-icon svg { display: block; }
/* Parents with no subtopics — a plain bordered row (matches the accordion cards). */
.at-acc-flat {
  display: flex; align-items: center; gap: 0.55rem; padding: 0.7rem 0.85rem;
  background: #fff; border: 1px solid #e2e6ee; border-radius: 10px;
  text-decoration: none; color: var(--color-text);
  font-family: var(--font-family); font-size: 0.95rem; font-weight: 600; letter-spacing: -0.006em;
  transition: border-color 0.16s, box-shadow 0.16s;
}
@media (hover: hover) { .at-acc-flat:hover { border-color: color-mix(in srgb, var(--ti-accent) 38%, #e2e6ee); box-shadow: 0 2px 10px rgba(15, 26, 46, 0.04); text-decoration: none; } }
.at-acc-flat-icon { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; color: var(--ti-accent, #5d6b7e); flex: none; }
.at-acc-flat-icon svg { width: 19px; height: 19px; display: block; }
.at-acc-flat-name { flex: 1 1 auto; min-width: 0; }
.at-acc-flat-chev { flex: none; color: #b8c2d2; display: inline-flex; }
.at-acc-flat-chev svg { transform: rotate(-90deg); width: 16px; height: 16px; display: block; }

