  }
  .topic-intelligence-panel .sidebar-card-title {
    color: #5d6b7e;
    font-family: var(--font-family);
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.13em;
    line-height: 1.2;
    text-transform: uppercase;
