  body.app-mode:not(.home-search) .topic-layout:not(.is-custom) #section-newsfeed .news-list .news-card:first-child .news-card-link { padding-top: 1.15rem; }
  #section-newsfeed .newsfeed-card .newsfeed-foot { padding: 0 18px 14px; }
