.trend-card-aibtn svg { flex: none; }
@media (hover: hover) { .trend-card-aibtn:hover { border-color: color-mix(in srgb, var(--color-primary) 40%, var(--color-surface-border)); color: var(--color-primary); background: color-mix(in srgb, var(--color-primary) 5%, #fff); } }
.trend-card-aibtn-close { display: none; }
/* Sparkle while closed ↔ weighted X while open, matching the label swap (#img590). */
.trend-card-aibtn-xic { display: none; }
.trend-card-aibtn[aria-expanded="true"] .trend-card-aibtn-spark { display: none; }
