.im-related-chip-tx { display: block; max-width: 220px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* Extra chips past the first row stay hidden until "+N more" expands them. */
.im-related-chip.is-extra { display: none; }
.im-related-chips.is-expanded .im-related-chip.is-extra { display: inline-flex; }
.im-related-more {
  display: inline-flex; align-items: center; padding: 5px 11px; border-radius: 999px;
  border: 1px dashed var(--color-surface-border); background: none; cursor: pointer;
  font-family: var(--font-family); font-size: 0.78rem; font-weight: 600; color: var(--color-text-muted);
  transition: border-color .14s, color .14s, background .14s;
}
@media (hover: hover) { .im-related-more:hover { border-color: color-mix(in srgb, var(--color-primary) 32%, var(--color-surface-border)); color: var(--color-primary); background: color-mix(in srgb, var(--color-primary) 4%, #fff); } }
.im-logo { display: inline-flex; width: 30px; height: 30px; flex: none; align-items: center; justify-content: center; border-radius: 9px; background: var(--color-primary); color: #fff; }
.im-logo svg { width: 16px; height: 16px; }
.im-brandname { font-family: var(--font-display); font-size: 1.34rem; font-weight: 700; letter-spacing: -0.015em; color: var(--color-text); }
.im-head-actions { display: inline-flex; align-items: center; gap: 8px; flex: none; }

/* Prominent section headers — same treatment for Article Overview + AI Brief. */
.im-section + .im-section { margin-top: 22px; }
.im-section-title { display: flex; align-items: center; gap: 7px; margin: 0 0 11px; font-family: var(--font-display); font-size: 1.04rem; font-weight: 700; letter-spacing: -0.012em; color: #1c3a6b; }
/* Section title WITH a glyph badge (Sources & Coverage) — matches the brief
   section headers (#129). The badge keeps the blue glyph; the title text follows. */
.im-section-title--icon { gap: 9px; color: #122451; }
.im-section-title--icon .ai-result-sub-ic svg { width: 14px; height: 14px; color: #1d4ed8; }
.im-section-title svg { width: 15px; height: 15px; color: var(--color-primary); }
.im-section-title--brief { color: var(--color-primary); }

/* Article Overview — one cohesive card. */
.im-article { padding: 15px 17px; background: color-mix(in srgb, var(--color-primary) 3%, #fff); border: 1px solid var(--color-surface-border); border-radius: 14px; }
.im-article .im-section-title { font-size: 0.76rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; font-family: var(--font-family); color: var(--color-primary); margin-bottom: 10px; }
.im-article-title { margin: 0 0 10px; font-family: var(--font-display); font-size: 1.16rem; line-height: 1.28; font-weight: 600; letter-spacing: -0.012em; color: #16243d; }
.im-article-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 0.82rem; color: var(--color-text-muted); }
/* Publisher rendered as a brand pill (like the homepage/topic source chips). */
/* Trend category as a brand pill (matches the publisher chip). */
.im-article-summary { margin: 11px 0 0; font-size: 0.9rem; line-height: 1.55; color: var(--color-text); }
/* Discreet, centered second pathway to the source at the end of the AI brief. */
.im-brief-source { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 20px auto 4px; padding: 6px 4px; font-size: 0.8rem; font-weight: 600; color: var(--color-text-muted); text-decoration: none; transition: color .14s; }
@media (hover: hover) { .im-brief-source:hover { color: var(--color-primary); text-decoration: underline; text-underline-offset: 2px; } }
.im-brief-source svg { width: 12px; height: 12px; }

/* News v3 — source · time ABOVE the title; title sits directly over summary. */
.im-article-meta--top { margin: 0 0 9px; }

/* Prev / Next story — clean arrow links above the article card. */

/* Quicklinks — discreet text links inside the overview card (View Original ·
   Sources · Ask AI · Web Search). They free the space the action chips used. */
.im-quicklinks { display: flex; flex-wrap: wrap; align-items: center; margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--color-surface-border); }
.im-qlink { display: inline-flex; align-items: center; gap: 4px; padding: 3px 0; font-family: var(--font-family); font-size: 0.82rem; font-weight: 600; color: #1d4ed8; background: none; border: none; cursor: pointer; text-decoration: none; transition: color .14s; }
@media (hover: hover) { .im-qlink:hover { text-decoration: underline; text-underline-offset: 2px; } }
.im-qlink svg { width: 11px; height: 11px; }
.im-qlink[aria-expanded="true"] { color: #1e3a8a; text-decoration: underline; text-underline-offset: 2px; }
/* Divider only for the text-link quicklinks (tab/search views) — NOT the
   button-styled .im-over-links pills, where a stray border-right broke the
   rounded shape. */
.im-quicklinks .im-qlink:not(:last-child) { margin-right: 11px; padding-right: 11px; border-right: 1px solid var(--color-surface-border); }

/* Sources & Coverage — final card listing the cited sources as a link list. */
/* Clean list (not bordered buttons): hyperlinked title, publisher beneath, thin
   dividers. Title is the link; when we only have the publisher domain, that IS
   the title. */
/* Separator above Sources & Coverage so it reads as its own block, distinct from
   the AI Brief above it (#113). */
.im-coverage { border-top: 1px solid var(--color-surface-border); padding-top: 18px; }
/* Trend briefs render coverage inline in the brief body (not a sibling section). */
.im-coverage--inline { margin-top: 22px; }
.im-coverage-list { display: flex; flex-direction: column; }
.im-cov-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 9px 2px; border: none; border-radius: 0; background: none; text-decoration: none; color: var(--color-text); border-bottom: 1px solid color-mix(in srgb, var(--color-surface-border) 70%, transparent); transition: none; }
.im-cov-row:last-child { border-bottom: none; }
.im-cov-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
/* Muted slate-blue link (less saturated than the old royal blue, #84). */
.im-cov-title { font-family: var(--font-family); font-size: 0.9rem; font-weight: 500; line-height: 1.4; color: #3a4a66; display: -webkit-box; -webkit-line-clamp: 2; line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.im-cov-row { align-items: flex-start; padding-top: 10px; padding-bottom: 10px; }
/* No whole-row underline on hover (#84) — just deepen the title colour. */
@media (hover: hover) { .im-cov-row:hover, .im-cov-row:hover .im-cov-title, .im-cov-row:hover .im-cov-host { text-decoration: none; } }
@media (hover: hover) { .im-cov-row:hover .im-cov-title { color: #1f2d4d; } }
.im-cov-host { font-size: 0.73rem; color: var(--color-text-muted); }
/* No ↗ arrows on AI-insight source rows anywhere (#img592). */
.im-cov-row svg { display: none; }

/* Sticky bar carries the affordances: prev/next chevrons + jump-up action links. */
.im-condensed-top { display: flex; align-items: center; gap: 8px; }
.im-condensed-top .im-condensed-title { flex: 1 1 auto; min-width: 0; }
/* Actions sit left, next to "View original" (#86) — not split to the right. */
.im-condensed-sub { display: flex; align-items: center; justify-content: flex-start; flex-wrap: wrap; gap: 6px 12px; margin-top: 3px; }
.im-condensed-meta { flex: none; }
.im-condensed-acts { display: inline-flex; align-items: center; flex: none; }
.im-condensed-meta + .im-condensed-acts { padding-left: 12px; border-left: 1px solid var(--color-surface-border); }
.im-cond-act { background: none; border: none; font-family: var(--font-family); font-size: 0.74rem; font-weight: 600; color: #1d4ed8; cursor: pointer; padding: 2px 0; transition: color .14s; }
@media (hover: hover) { .im-cond-act:hover { text-decoration: underline; text-underline-offset: 2px; } }
.im-cond-act[aria-expanded="true"] { color: #1e3a8a; text-decoration: underline; text-underline-offset: 2px; }
.im-cond-act:not(:last-child) { margin-right: 9px; padding-right: 9px; border-right: 1px solid var(--color-surface-border); }
.im-cond-arrow { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; flex: none; border: 1px solid var(--color-surface-border); border-radius: 7px; background: #fff; color: var(--color-text); cursor: pointer; transition: border-color .14s, color .14s; }
@media (hover: hover) { .im-cond-arrow:hover { border-color: var(--color-primary); color: var(--color-primary); } }
.im-cond-arrow--ghost { visibility: hidden; }

/* AI Brief — disclaimer (tight under the label, not italic), then actions, a
   clear rule, then the content. */
.im-section-title--brief { font-size: 1.2rem; color: #1b3a8c; }
.im-section-title--brief svg { color: #1b3a8c; }
.im-brief-section .im-section-title--brief { margin-bottom: 7px; }

/* Inline "AI-generated" tag — sits at the top of the brief body so the prose
   itself is unmistakably marked (the "AI Brief" header is above the buttons +
   rule). Same navy chip language as the trending-card badge. */
.aigen-tag { display: inline-flex; align-items: center; gap: 5px; margin: 0 0 12px; padding: 2px 9px 2px 7px; border-radius: 999px; background: color-mix(in srgb, var(--color-primary) 8%, #fff); border: 1px solid color-mix(in srgb, var(--color-primary) 16%, transparent); font-size: 0.64rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--color-primary); }
.aigen-tag svg { width: 11px; height: 11px; }

/* ===== News AI Insights modal refinements (#83-#94) ===== */
/* AI Brief header: navy square sparkle logo + BLACK title (#93/#94). */
.im-brief-head { display: flex; align-items: center; gap: 10px; margin: 0 0 8px; }
.im-brief-logo { display: inline-flex; width: 28px; height: 28px; flex: none; align-items: center; justify-content: center; border-radius: 8px; background: var(--color-primary); color: #fff; }
.im-brief-logo svg { width: 15px; height: 15px; }
.im-brief-title { font-family: var(--font-display); font-size: 1.2rem; font-weight: 700; letter-spacing: -0.015em; text-transform: none; color: #16243d; }

/* "Sources:" line under the AI Brief — clickable jump to Sources & Coverage (#88). */
/* Hugs the text (inline-block), not the full modal width; subtle tint + a light
   colour shift on hover, no underline (#105). */

/* "✦ = AI-generated text" legend beneath the sources line (#88). */
.im-aiflag-legend { display: flex; align-items: center; gap: 3px; margin: 6px 0 0; font-size: 0.76rem; font-weight: 600; color: var(--color-text-muted); }
.im-aiflag-legend svg { width: 13px; height: 13px; color: #1d4ed8; flex: none; }
/* Larger legend used at the TOP of a brief (replaces the old "AI Brief" title) —
   the AI-generated marker now heads the section, above the disclaimer (#124). */
.im-aiflag-legend--lg { gap: 7px; margin: 0 0 7px; font-size: 0.98rem; color: var(--color-text); }
.im-aiflag-legend--lg svg { width: 18px; height: 18px; }

/* Inline AI sparkle on the first line of each AI-generated section — the same
   blue used to flag AI-generated text everywhere else (.ai-spark-mark). */
.ai-flag { display: inline-flex; align-items: center; vertical-align: -2px; margin-right: 5px; color: #1d4ed8; }
.ai-flag svg { width: 13px; height: 13px; }

/* Story Prev/Next pills in the top header row (#87). */
.im-head-nav { display: inline-flex; align-items: center; gap: 6px; flex: none; }
.im-head-navbtn { display: inline-flex; align-items: center; gap: 3px; padding: 5px 10px; border: 1px solid var(--color-surface-border); border-radius: 999px; background: #fff; font-family: var(--font-family); font-size: 0.76rem; font-weight: 600; color: var(--color-text); cursor: pointer; transition: border-color .14s, color .14s, background .14s; }
@media (hover: hover) { .im-head-navbtn:hover:not(:disabled) { border-color: var(--color-primary); color: var(--color-primary); background: color-mix(in srgb, var(--color-primary) 5%, #fff); } }
.im-head-navbtn:disabled { opacity: 0.4; cursor: default; }
.im-head-navbtn svg { width: 14px; height: 14px; }
@media (max-width: 560px) { .im-head-navbtn span { display: none; } .im-head-navbtn { padding: 5px 7px; } }

/* Discreet second sticky: appears below the main header once the AI Brief
   header scrolls up under it (#89). */
.im-brief-sticky { display: none; align-items: center; gap: 8px; padding: 8px 18px; border-top: 1px solid color-mix(in srgb, var(--color-surface-border) 70%, transparent); background: color-mix(in srgb, var(--color-primary) 3%, #fff); }
.is-brief-scrolled .im-brief-sticky { display: flex; }
.im-brief-sticky-logo { display: inline-flex; align-items: center; color: var(--color-primary); flex: none; }
.im-brief-sticky-logo svg { width: 14px; height: 14px; }
.im-brief-sticky-title { font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; text-transform: none; color: var(--color-text); flex: none; }
.im-brief-sticky-note { font-size: 0.74rem; color: var(--color-text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }

/* Discreet inline AI marker (blue sparkle) + the one-line legend that defines it
   at the top of a list. Used on trending summaries (and reusable across the board). */
.ai-spark-mark { display: inline-flex; align-items: center; color: #1d4ed8; }
.ai-spark-mark svg { width: 12px; height: 12px; }
.trend-card-summary .ai-spark-mark { margin-right: 5px; vertical-align: -2px; }
/* Legend pill at the top-left of the trend list body — defines the two card
   glyphs (sparkle = AI text, up-arrow = Google Trends). A faint pill; the two
   items wrap as whole units when the card is narrow. */
.trend-legend-row { display: flex; justify-content: flex-start; padding: 11px 16px 0; }
/* Solo "= AI-generated text" legend — a touch bigger than the old card legend
   (but smaller than the modal), tighter below (#166). */
.trend-legend--solo .trend-legend-item { font-size: 0.68rem; font-weight: 600; color: var(--color-text-muted); }
.trend-legend--solo .ai-spark-mark svg { width: 11px; height: 11px; }
.trend-legend--solo { padding: 4px 10px; }
/* In the Trending modal, the legend shares the category-chooser line (chooser
   left, legend right), with clear breathing room before the trend grid. */
.trend-controls-legend { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 16px; flex-wrap: wrap; margin-bottom: 18px; }
.trend-controls-legend .trend-controls { margin: 0; }
.trend-controls-legend .trend-legend-row { padding: 0; justify-content: flex-end; }
/* A squared-off label block (not a pill) so it reads as an info marker about the
   list below, not a tappable control (#80). */
/* A touch darker than before so the provenance pill reads at a glance (#img115). */
.trend-legend { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; padding: 5px 11px; border-radius: 7px; background: color-mix(in srgb, var(--color-text) 6.5%, #fff); border: 1px solid color-mix(in srgb, var(--color-surface-border) 95%, transparent); }
.trend-legend-item { display: inline-flex; align-items: center; gap: 5px; font-size: 0.68rem; font-weight: 600; color: #4a5a75; white-space: nowrap; }
.trend-legend-item .ai-spark-mark svg { width: 11px; height: 11px; }
/* Trending modal "View more trends" — reveals the next batch of cards. */
.trend-loadmore-row { display: flex; justify-content: center; padding: 18px 0 6px; }
.trend-loadmore { display: inline-flex; align-items: center; gap: 8px; padding: 10px 20px; border: 1px solid var(--color-surface-border); border-radius: 999px; background: #fff; cursor: pointer; font-family: var(--font-family); font-size: 0.88rem; font-weight: 650; color: var(--color-primary); transition: border-color .14s, background .14s, transform .06s; }
@media (hover: hover) { .trend-loadmore:hover { border-color: color-mix(in srgb, var(--color-primary) 32%, var(--color-surface-border)); background: color-mix(in srgb, var(--color-primary) 4%, #fff); } }
.trend-loadmore:active { transform: translateY(1px); }
.trend-loadmore-count { font-size: 0.78rem; font-weight: 600; color: var(--color-text-muted); }
.trend-legend-trend-ic { display: inline-flex; align-items: center; color: #475569; }
/* "Earlier" — recently-trending (not live). Clearly separated from the live grid;
   past cards swap the green up-arrow for a muted clock so they don't read as live. */
.trend-card--past .trend-card-icon { color: var(--color-text-light); }
.trend-legend-trend-ic svg { width: 12px; height: 12px; }

/* AI provenance — the consistent "this is AI-generated, grounded in these
   sources" marker. Full form (brief surfaces, no badge): a "Sources: A, B +N"
   line under the AI Brief disclaimer. Compact form (trending cards): a "✦ AI ·
   N sources" chip. See js/utils/ai-provenance.js. */
.ai-prov-slot:empty { display: none; }
.ai-prov { display: flex; align-items: baseline; flex-wrap: wrap; gap: 6px; font-size: 0.76rem; line-height: 1.4; color: var(--color-text-muted); }
.ai-prov-slot .ai-prov { margin: -2px 0 13px; }
.aii-prov-slot .ai-prov { margin: -2px 0 12px; }
.ai-prov-srcs { display: inline; }
.ai-prov-srcs-lead { font-weight: 700; color: #54607a; letter-spacing: 0.02em; }
.ai-prov-srcs--feed { font-style: italic; }
/* Compact card chip + source count. */
.ai-prov--compact { margin-top: 6px; gap: 5px; font-size: 0.66rem; align-items: center; }
.ai-prov-badge { display: inline-flex; align-items: center; gap: 3px; padding: 1px 7px 1px 5px; border-radius: 999px; background: color-mix(in srgb, var(--color-primary) 8%, #fff); border: 1px solid color-mix(in srgb, var(--color-primary) 15%, transparent); color: var(--color-primary); font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase; }
.ai-prov-badge svg { width: 10px; height: 10px; }
.ai-prov--compact .ai-prov-sep { color: var(--color-text-light); }
