.im-acc { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows .28s cubic-bezier(.4, 0, .2, 1), padding-top .28s cubic-bezier(.4, 0, .2, 1), opacity .2s ease; }
