@media (hover: hover) { .im-wscat .im-source-row:hover { background: color-mix(in srgb, var(--color-primary) 4%, transparent); color: var(--color-primary); } }
@media (hover: hover) { .im-wscat .im-source-row:hover svg { color: var(--color-primary); } }
