.im-leave-go { display: inline-flex; align-items: center; gap: 7px; padding: 8px 15px; border: 1px solid color-mix(in srgb, var(--color-primary) 26%, var(--color-surface-border)); border-radius: 9px; background: #fff; color: var(--color-primary); cursor: pointer; font-family: var(--font-family); font-size: 0.8rem; font-weight: 600; transition: background .14s, border-color .14s; }
@media (hover: hover) { .im-leave-go:hover { background: color-mix(in srgb, var(--color-primary) 6%, #fff); border-color: color-mix(in srgb, var(--color-primary) 42%, var(--color-surface-border)); } }
.im-leave-go svg { width: 13px; height: 13px; stroke: currentColor; }

/* Generating state — centered, animated, occupies space the brief will fill. */
.im-gen { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 26px 12px 30px; }
.im-gen-spark { width: 40px; height: 40px; display: inline-flex; align-items: center; justify-content: center; border-radius: 12px; background: var(--color-primary); color: #fff; animation: imGenPulse 1.5s ease-in-out infinite; }
