.pdir-topichost .aii-fi-acclist .aii-fi-acc { display: block; padding: 0 !important; margin: 0 !important; }
.pdir-topichost .aii-fi-acclist .aii-fi-accsum {
  display: flex !important; align-items: center !important;
  width: 100%; box-sizing: border-box;
  min-height: 52px; padding: 0 12px !important; margin: 0 !important;
  line-height: 1.3;
}
.pdir-topichost .aii-fi-acclist .aii-fi-acc-ic { align-self: center; margin: 0 !important; }
.pdir-topichost .aii-fi-acclist .aii-fi-acc-tx { display: flex; align-items: center; min-height: 0; }
.pdir-topichost .aii-fi-acclist .aii-fi-acc-chev { align-self: center; margin-left: auto; }

/* ═══════════════ revamp761 ═══════════════════════════════════════════════ */

/* Parent topic rows lighter again, and an open card separates its header from
   the topic grid with a rule plus real breathing room. */
.pdir-card-name { font-weight: 600 !important; letter-spacing: -0.01em; }
.pdir-card.is-open > .pdir-cardhead { border-bottom: 1px solid #e7ecf3; }
.pdir-card.is-open .pdir-cardbody { padding-top: 16px !important; padding-bottom: 18px !important; }
.pdir-card.is-open .pdir-grid { gap: 9px; }

/* ═══════════════ revamp762 ═══════════════════════════════════════════════ */

/* ── AI Insights remade: the brief IS the page ────────────────────────────
   Two compact resource accordions (AI Prompts / External AI Models) under a
   tiny eyebrow, then "The AI Brief" — three always-open subsections (Catch Up
   / Deep Dive / 101 Info) whose stories are preview-and-expand rows. */

/* Per-subsection accent: blue = Catch Up, amber = Deep Dive, teal = 101 Info. */

/* Eyebrow + compact single-line resource accordions. */

/* The AI Brief band: bold navy heading + jump chips over a STRONG navy rule —
   the one heavy line on the page, so the brief reads as the main event. */

/* Subsection headers: accent-tinted icon chip + title + one-liner. */

/* Story rows: headline + a two-line teaser, expanding to the full prose. */
.tai-story-sum {
  display: flex; align-items: flex-start; gap: 12px; width: 100%;
  padding: 13px 2px; border: none; background: none; cursor: pointer; text-align: left;
  -webkit-tap-highlight-color: transparent;
}
.tai-story-tx { display: flex; flex-direction: column; gap: 3px; flex: 1; min-width: 0; }
.tai-story-sum .im-msec-name {
  margin: 0; font-family: var(--font-display); font-size: 0.96rem; font-weight: 650;
  letter-spacing: -0.01em; color: #26375a; line-height: 1.35;
}
.tai-story-prev {
  font-family: var(--font-family); font-size: 0.82rem; color: #71809b; line-height: 1.5;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.tai-story-chev { flex: none; display: inline-flex; color: #a8b4c9; margin-top: 4px; transition: transform .18s ease, color .12s ease; }
.tai-story-chev svg { width: 16px; height: 16px; }
.im-msec.is-open > .tai-story-sum .tai-story-chev { transform: rotate(180deg); color: #6f83a6; }
.im-msec.is-open > .tai-story-sum .tai-story-prev { display: none; }
@media (hover: hover) {
  .tai-story-sum:hover .im-msec-name { color: #1d4ed8; }
  .tai-story-sum:hover .tai-story-chev { color: #1d4ed8; }
}

/* One quiet provenance line per brief, above its first story. */
.tai-prov {
  display: flex; align-items: center; gap: 7px; margin: 12px 2px 0;
  font-family: var(--font-family); font-size: 0.72rem; font-weight: 600; color: #94a1b5;
}
.tai-prov-ai { display: inline-flex; align-items: center; gap: 5px; color: #7c8aa5; }
.tai-prov-ai svg { width: 11px; height: 11px; }
.tai-prov-sep { color: #c3cbd8; }

/* Loading shimmer inside a subsection shouldn't balloon the part. */

@media (max-width: 560px) {
  .tai-story-sum { padding: 12px 2px; gap: 10px; }
  .tai-story-sum .im-msec-name { font-size: 0.92rem; }
  .tai-story-prev { font-size: 0.79rem; }
}

/* ═══ Featured Topics / Featured Prompts cards (revamp763) ═══════════════════
   The grey hero zone now holds ONLY the search hero. The old quicklinks strip
   became two proper cards at the top of the WHITE band: matching title, chip
   list, and a footer link out to the full directory — one consistent shape. */
.home-featured {
  display: grid; grid-template-columns: 1fr; gap: 0.9rem; min-width: 0;
  margin-bottom: 1.2rem;
}
@media (min-width: 720px) {
  /* Topics get the wider column (60/40) — it carries more chips, so the two
     cards land at roughly the same height. */
  .home-featured { grid-template-columns: minmax(0, 3fr) minmax(0, 2fr); gap: 1.1rem; margin-bottom: 1.5rem; }
}
@media (min-width: 1024px) {
  /* Inside the desktop .home-sections grid (news col + trending col): span both. */
  body.home-search .home-sections .home-featured { grid-column: 1 / -1; }
}
.hf-card {
  display: flex; flex-direction: column; min-width: 0;
  background: #fff; border: 1px solid #e4eaf3; border-radius: 14px;
  padding: 0.85rem 1rem 0.6rem;
  box-shadow: 0 6px 18px -14px rgba(31, 49, 99, 0.18);
  --hf-accent: #2563eb; --hf-tint: #eef3fc;
}
.hf-card--prompts { --hf-accent: #4f46e5; --hf-tint: #eef0fc; }
.hf-head { display: flex; align-items: center; gap: 9px; margin-bottom: 0.4rem; }
.hf-ic {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border-radius: 7px; background: var(--hf-tint); color: var(--hf-accent);
  margin-top: 1px;
}
.hf-ic svg { width: 14px; height: 14px; }
.hf-title {
  margin: 0; font-family: var(--font-display);
  font-size: 1.12rem; font-weight: 800; letter-spacing: -0.018em; color: #1a2740; line-height: 1.25;
}
.hf-sub { margin: 0 0 0.85rem; font-family: var(--font-family); font-size: 0.78rem; color: #76829b; line-height: 1.4; }
.hf-chips { display: flex; flex-wrap: wrap; align-content: flex-start; gap: 6px 7px; min-width: 0; flex: 1 1 auto; }
/* Chips read a touch stronger on the white card than the old grey-zone pills,
   and pick up the card's accent on hover. */
/* Dynamic chip counts by viewport — the DOM holds the full set (12 topics /
   6 prompts); narrower screens simply show fewer. */
.hf-foot {
  display: flex; justify-content: flex-start; margin-top: 0.9rem;
  border-top: none; padding: 0 2px 4px;
}
.hf-cta {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 4px 2px; border: none; background: none;
  font-family: var(--font-family); font-size: 0.86rem; font-weight: 700; color: #3d5da8;
  white-space: nowrap; cursor: pointer; text-decoration: none;
  transition: color .12s;
}
.hf-cta svg { flex: none; transition: transform .14s ease; }
@media (hover: hover) {
  .hf-cta:hover { color: var(--hf-accent); }
  .hf-cta:hover svg { transform: translateX(2px); }
}
@media (max-width: 560px) {
  .hf-card { padding: 0.8rem 0.9rem 0.55rem; }
  .hf-chips { gap: 6px; }
}
/* Brand-family icon chip on the news heads (news = red). */

/* ═══ Topic pages without tabs (revamp763) ═══════════════════════════════════
   The News Feed / AI Insights / Web Resources tab strip is gone. The topic
   LANDING = Daily Intelligence card + gateway cards + news feed; each former
   tab is a flip sub-page with a sticky "Back to {Topic}" bar in the sub-header
   where the tabs used to live. */

/* Back bar — replaces .topic-paths-nav inside .topic-subnav-controls. */
.topic-subnav-controls--back .topic-backbar-inner {
  max-width: var(--max-width, 1280px); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 8px 2rem;
}
@media (max-width: 640px) { .topic-subnav-controls--back .topic-backbar-inner { padding: 8px 1rem; } }
.topic-backbar {
  display: inline-flex; align-items: center; gap: 7px; min-width: 0;
  font-family: var(--font-family); font-size: 0.86rem; font-weight: 700; color: #2c4f9e;
  text-decoration: none; padding: 2px 0; transition: color .12s;
}
.topic-backbar svg { flex: none; }
.topic-backbar span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (hover: hover) { .topic-backbar:hover { color: #1d4ed8; text-decoration: none; } }
.topic-backbar-here {
  flex: none; font-family: var(--font-family); font-size: 0.72rem; font-weight: 700;
  letter-spacing: 0.06em; text-transform: uppercase; color: #8a98b0;
}

/* ── Landing: Daily Intelligence card (the jewel) ─── */
.topic-home { display: flex; flex-direction: column; min-width: 0; width: 100%; }
.tdi-card {
  display: block; position: relative; text-decoration: none;
  border-radius: 18px; border: 1px solid #d5e0f4;
  background: linear-gradient(135deg, #f7faff 0%, #eef3fc 55%, #e8effb 100%);
  padding: 1.15rem 1.3rem 0.95rem; overflow: hidden;
  transition: border-color .15s, box-shadow .15s, transform .15s;
}
@media (hover: hover) {
  .tdi-card:hover { border-color: #b9cbeb; box-shadow: 0 16px 32px -20px rgba(31, 49, 99, 0.4); transform: translateY(-1px); text-decoration: none; }
}
.tdi-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 0.7rem; }
.tdi-date { font-family: var(--font-family); font-size: 0.76rem; font-weight: 650; color: #5b6c8c; white-space: nowrap; }
.tdi-summary { margin: 0; font-family: var(--font-family); font-size: 0.92rem; line-height: 1.55; color: #42506b; max-width: 72ch; }
/* Three section mini-tiles inside the card — a preview of the briefing's shape. */
/* CTA reads as a real button — the card's one clear action. */

/* ── Landing: gateway cards (Web Resources / AI Prompts) ─── */

/* ── Landing: news feed under a homepage-style header ─── */
.topic-home .topic-news-wrap { margin-top: 2.3rem; width: 100%; }
/* The old topic pages hid the feed header (the tab already named the section);
   the new landing needs it visible again — same look as the homepage head.
   !important counters the legacy `#topic-tab-body #section-newsfeed
   .newsfeed-head { display: none !important }` hider. */
#topic-tab-body #section-newsfeed .newsfeed-head--topic,
body.app-mode:not(.home-search) .topic-layout:not(.is-custom) #section-newsfeed .newsfeed-head--topic { display: block !important; position: static; margin: 0 0 2px; padding: 0 2px 12px; background: transparent; border-bottom: 1px solid #e4e8f0; }
#topic-tab-body #section-newsfeed .newsfeed-head--topic .newsfeed-title,
body.app-mode:not(.home-search) .topic-layout:not(.is-custom) #section-newsfeed .newsfeed-head--topic .newsfeed-title { display: flex !important; font-size: 1.24rem; color: #1a2740; border-bottom: none; background: transparent; padding: 0; margin: 0; min-height: 0; }

/* Sub-page prompt rows: show each prompt's one-line description under its name. */
.aii-fi-acc-desc {
  display: block; font-family: var(--font-family); font-size: 0.78rem; font-weight: 400;
  color: #76829b; line-height: 1.4; margin-top: 2px;
}

@media (max-width: 560px) {
  .tdi-card { padding: 1rem 1rem 0.85rem; border-radius: 16px; }
  .topic-home .topic-news-wrap { margin-top: 1.4rem; }
}

/* ═══ Daily Intelligence page (revamp763) ════════════════════════════════════ */
.di-page { display: flex; flex-direction: column; min-width: 0; width: 100%; }
.di-head { padding: 0 2px 1.1rem; border-bottom: 1.5px solid #d3d9e4; margin-bottom: 1.4rem; }
.di-meta {
  display: flex; align-items: center; flex-wrap: wrap; gap: 7px; margin-top: 0.7rem;
  font-family: var(--font-family); font-size: 0.74rem; font-weight: 600; color: #94a1b5;
}
.di-meta-ai { display: inline-flex; align-items: center; gap: 5px; color: #7c8aa5; }
.di-meta-ai svg { width: 11px; height: 11px; }
.di-meta-sep { color: #c3cbd8; }
/* Jump chips under the page head — one per section, accent-dotted. */
.di-body { display: flex; flex-direction: column; gap: 1.3rem; min-width: 0; }
/* Each section is its own card with a slim accent bar on top — the page reads
   as three clear chapters instead of one continuous scroll. */
.di-sec {
  min-width: 0; --di-accent: #2563eb; --di-tint: #eef3fc;
  background: #fff; border: 1px solid #e8edf5; border-radius: 14px;
  border-top: 3px solid var(--di-accent);
  padding: 1.05rem 1.2rem 1.1rem;
  scroll-margin-top: calc(var(--nav-h, 60px) + var(--subnav-height, 96px) + 14px);
}
.di-sec--amber { --di-accent: #d97706; --di-tint: #fdf3e4; }
.di-sec--teal  { --di-accent: #0d9488; --di-tint: #e5f5f3; }
.di-sec-head { display: flex; align-items: center; gap: 11px; margin-bottom: 0.8rem; padding-bottom: 0.75rem; border-bottom: 1px solid #eef2f8; }
.di-sec-ic {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  width: 34px; height: 34px; border-radius: 9px; background: var(--di-tint); color: var(--di-accent);
}
.di-sec-ic svg { width: 18px; height: 18px; }
.di-sec-headtx { min-width: 0; }
.di-sec-title {
  margin: 0; font-family: var(--font-display); font-size: 1.08rem; font-weight: 800;
  letter-spacing: -0.018em; color: #1a2740;
}
.di-sec-sub { margin: 1px 0 0; font-family: var(--font-family); font-size: 0.78rem; color: #76829b; line-height: 1.4; }
.di-sec-body { font-size: 0.92rem; line-height: 1.62; color: #34405a; }
.di-sec-body p { margin: 0 0 0.8em; }
.di-sec-body p:last-child { margin-bottom: 0; }
.di-sec-body p strong { color: #16233d; }
/* Catch Up: each bold-led development reads as its own accent-ruled item. */
.di-sec--blue .di-sec-body p {
  padding: 2px 0 2px 13px; border-left: 3px solid color-mix(in srgb, var(--di-accent) 32%, #fff);
  margin-bottom: 0.85em;
}
/* 101 Info: each concept explainer sits on its own soft tinted panel. */
.di-sec--teal .di-sec-body p {
  background: color-mix(in srgb, var(--di-tint) 55%, #fff);
  border: 1px solid color-mix(in srgb, var(--di-accent) 14%, #fff);
  border-radius: 10px; padding: 10px 13px; margin-bottom: 9px;
}
/* Curated links — an OPEN, visible list (never buried in an accordion). */
.di-read {
  display: flex; align-items: center; gap: 10px; padding: 9px 12px; min-width: 0;
  border: 1px solid #e8edf5; border-radius: 10px; background: #fbfcfe;
  text-decoration: none; transition: background .12s, border-color .12s;
}
@media (hover: hover) { .di-read:hover { background: #fff; border-color: color-mix(in srgb, var(--di-accent, #2563eb) 35%, #fff); text-decoration: none; } }
.di-read-tx { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.di-read-title {
  font-family: var(--font-family); font-size: 0.85rem; font-weight: 650; color: #2b3a58;
  line-height: 1.35; overflow-wrap: anywhere;
}
.di-read-meta { font-family: var(--font-family); font-size: 0.72rem; color: #94a1b5; }
.di-read > svg { flex: none; margin-left: auto; color: #a8b4c9; }
.di-sec--more { --di-accent: #8a98b0; border-top-color: #d3d9e4; }
.di-sec--more .di-sec-head { border-bottom: none; padding-bottom: 0; margin-bottom: 0.55rem; }
@media (max-width: 560px) {
  .di-head { padding-bottom: 0.9rem; margin-bottom: 1.1rem; }
  .di-body { gap: 1.5rem; }
  .di-sec-ic { width: 30px; height: 30px; }
  .di-sec-ic svg { width: 16px; height: 16px; }
}

/* ═══ Search page viewport repair + back-target polish (revamp764) ═══════════
   revamp758 made Search a "page" but collapsed the panel to content height —
   the home page peeked out below and took the scroll wheel. The panel now
   pins to the full viewport (top nav → bottom) and is the ONE scroller in
   both collapsed and expanded states. */
.aii-nav-dd-search { bottom: 0; height: auto; max-height: none; }
.aii-nav-dd-search .aii-nav-dd-inner { min-height: 100% !important; height: auto !important; }
/* One scroll: no inner scrollers in either state (the :has(expanded) rules
   above only covered the expanded state). */
.aii-nav-dd-search .aii-nav-dd-scrollwrap,
.aii-nav-dd-search .aii-nav-dd-scroll {
  overflow: visible !important; height: auto !important; max-height: none !important; flex: none !important;
}
.aii-nav-dd-search .search-panel--modal { height: auto; min-height: 0; }
.aii-nav-dd-search .search-panel-results,
.aii-nav-dd-search .search-panel-results-inner {
  overflow: visible !important; max-height: none !important; height: auto !important;
}
/* Back bar shares the content gutter (it sat 2px from the viewport edge). */
.aii-nav-dd-search > .aii-nav-dd-inner > .page-backbar { padding: 18px 2rem 0; }
@media (max-width: 640px) { .aii-nav-dd-search > .aii-nav-dd-inner > .page-backbar { padding: 16px 1rem 0; } }

/* ═══ Daily Intelligence v3 + topic landing two-column top (revamp765) ═══════ */
/* Shared topic-section header lockup — kicker + icon-chip title, matching the
   news feed head so every topic-page section speaks one language. */
.tsec-title {
  display: flex; align-items: center; margin: 0;
  font-family: var(--font-display); font-size: 1.24rem; font-weight: 800;
  letter-spacing: -0.02em; color: #1a2740;
}
.tsec-ic {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: 8px; margin-right: 9px;
  font-size: 0.95rem; line-height: 1;
}
.tsec-ic--di { background: #1d3a6b; color: #8ab4ff; }

/* Landing top: DI (with header) left, gateway cards in a side column right. */
.topic-top { display: flex; flex-direction: column; gap: 1.1rem; min-width: 0; }
.topic-top-main { min-width: 0; }
@media (min-width: 1024px) {
  .topic-top { display: grid; grid-template-columns: minmax(0, 1fr) 350px; gap: 1.4rem; align-items: end; }
}

/* DI landing card v3 — title + date INSIDE the card, summary, then a plain
   CTA link (no separator rule). */
.tdi-card--v3 { padding: 1.05rem 1.2rem 1rem; margin-top: 0; display: block; }
.tdi-card--v3 .tdi-card-title { margin: 0 0 0.6rem; font-size: 1.36rem; line-height: 1; align-items: center; }
.tdi-card--v3 .tdi-card-title .tsec-ic { margin-top: 0; }
.tdi-card--v3 .tdi-date {
  display: block; margin: 0 0 0.4rem;
  font-family: var(--font-family); font-size: 0.8rem; font-weight: 650; color: #26375a;
}
.tdi-card--v3 .tdi-date:empty { display: none; }
.tdi-card--v3 .tdi-summary { font-size: 0.92rem; }
.tdi-card--v3 .tdi-go { margin-top: 0.85rem; font-size: 0.88rem; }
.tdi-go { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-family); font-size: 0.84rem; font-weight: 750; color: #2c4f9e; white-space: nowrap; }
.tdi-go svg { flex: none; transition: transform .14s ease; }
@media (hover: hover) { .tdi-card--v3:hover .tdi-go { color: #1d4ed8; } .tdi-card--v3:hover .tdi-go svg { transform: translateX(2px); } }

/* ── DI page v3 ─── */
.di-head { padding-bottom: 1rem; }
.di-datebar {
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-top: 0.55rem;
  font-family: var(--font-family); font-size: 0.95rem;
}
.di-datebar:empty { display: none; }
.di-date-day { font-weight: 750; color: #26375a; }
.di-date-sep { color: #c3cbd8; }
.di-date-upd { font-weight: 600; color: #76829b; font-size: 0.85rem; }
.di-lede {
  margin: 0.6rem 0 0; font-family: var(--font-family);
  font-size: 1.02rem; line-height: 1.55; color: #34405a; max-width: 78ch; font-weight: 550;
}
.di-prov2 {
  display: inline-flex; align-items: center; gap: 6px; margin-bottom: 0.4rem;
  font-family: var(--font-family); font-size: 0.72rem; font-weight: 650; color: #94a1b5;
}
.di-prov2 svg { width: 11px; height: 11px; }
.di-body { gap: 1.6rem; }
.di-ov { min-width: 0; }
.di-ov-body { font-size: 0.96rem; line-height: 1.65; color: #2b3a58; }
.di-ov-body p { margin: 0 0 0.8em; }
.di-ov-body p:last-child { margin-bottom: 0; }
.di-briefs { min-width: 0; }
.dib { padding: 15px 0 14px; border-top: 1px solid #edf1f7; min-width: 0; }
.dib:first-of-type { border-top: none; padding-top: 4px; }
.dib-body { font-size: 0.93rem; line-height: 1.62; color: #34405a; }
.dib-body p { margin: 0; }
.dib-body p strong { color: #16233d; }
/* Per-item source chips — right where the reader's interest is. */
.dib-srcs { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.dib-srcs-label {
  font-family: var(--font-family); font-size: 0.66rem; font-weight: 750;
  letter-spacing: 0.07em; text-transform: uppercase; color: #a8b4c9; margin-right: 2px;
}
.dib-src {
