  padding: 3px 10px; border-radius: 999px; border: 1px solid #dfe6f2; background: #f8fafd;
  font-family: var(--font-family); font-size: 0.74rem; font-weight: 650; color: #45536e;
  text-decoration: none; transition: border-color .12s, color .12s, background .12s;
}
.dib-src span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dib-src svg { flex: none; width: 11px; height: 11px; color: #a8b4c9; }
@media (hover: hover) { .dib-src:hover { background: #fff; border-color: #b9cbeb; color: #1d4ed8; text-decoration: none; } .dib-src:hover svg { color: #1d4ed8; } }
@media (max-width: 560px) {
  .di-lede { font-size: 0.95rem; }
  .di-datebar { font-size: 0.88rem; }
}

/* ── Search as a real page (revamp765) ── */
.search-page {
  max-width: var(--max-width, 1280px); margin: 0 auto;
  padding: 0 2rem 3rem; min-height: calc(100dvh - var(--nav-h, 60px));
  display: flex; flex-direction: column; min-width: 0;
}
.search-page > .page-backbar { padding: 18px 2px 0; }
.search-page .search-page-host { flex: 1 1 auto; display: flex; flex-direction: column; min-width: 0; }
.search-page .search-panel--modal { height: auto; min-height: 0; flex: 1 1 auto; }
.search-page .search-panel-topfold { position: static; }
.search-page .search-panel-results,
.search-page .search-panel-results-inner { overflow: visible; max-height: none; height: auto; }
@media (max-width: 640px) { .search-page { padding: 0 1rem 2.4rem; } }

/* ── Trending page: hover highlight stays clear of the hairlines (revamp765) ──
   The row hover used to paint the full row, butting into the separator above
   (worst on the first row of each column). The highlight is now a rounded
   inset layer, so it never touches the rules above/below. */
@media (hover: hover) {
