  font-size: 0.9rem !important; font-weight: 600 !important;
  letter-spacing: 0 !important; color: #2b3a55 !important;
}
.ph-fitem-topic { font-size: 0.75rem !important; font-weight: 500 !important; }
.ph-fitem { padding: 0.62rem 2px !important; }

/* ── Build card ── */
.ph-build {
