}
.hb-all svg { width: 13px; height: 13px; }
@media (hover: hover) { .hb-all:hover { color: #1d4ed8; } }

/* ── Lead briefing + topic cards ── */
.hb-grid { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); gap: 14px; }
.hb-hero { min-width: 0; }
.hb-hero .tdi-card { height: 100%; position: relative; overflow: hidden; }
/* The art component is shared with topic pages (revamp980). */
.hb-hero .tdi-card .tdi-bodygrid,
.hb-hero .tdi-card .tdi-briefcol,
.hb-hero .tdi-card .tdi-expand { position: relative; z-index: 2; }
.hb-hero .tdi-card .tdi-briefcol { max-width: 60%; }
.hb-hero .tdi-card.is-evening { --tdi-art-ground: #101a33; background: #101a33 !important; }
.hb-hero .tdi-card.is-evening .tdi-today-title,
.hb-hero .tdi-card.is-evening .tdi-summary { color: #eef2fa !important; }
.hb-hero .tdi-card.is-evening .tdi-topiclabel,
.hb-hero .tdi-card.is-evening .tdi-date,
.hb-hero .tdi-card.is-evening .tdi-stamp-val,
.hb-hero .tdi-card.is-evening .tdi-stamp-ed { color: #a9b8d8 !important; }

.hb-cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.hb-card {
  display: flex; flex-direction: column; gap: 7px; min-width: 0;
  padding: 14px 15px 13px; border-radius: 13px;
  border: 1px solid color-mix(in srgb, #2f4d9e 12%, transparent);
  background: #fff; text-decoration: none !important;
  transition: border-color .14s ease, transform .14s ease;
}
.hb-card-head { display: flex; align-items: center; gap: 8px; min-width: 0; }
.hb-card-ic { flex: none; display: grid; place-items: center; width: 18px; height: 18px; color: #52678f; }
.hb-card-ic svg { width: 16px; height: 16px; display: block; }
.hb-card-name {
  font-family: var(--font-display); font-size: 0.95rem; font-weight: 700;
  letter-spacing: -0.012em; color: #172554; min-width: 0;
}
.hb-card-desc {
  font-family: var(--font-family); font-size: 0.82rem; line-height: 1.45; color: #5a6a8c;
  /* 3 lines, not 2 (#img579). Topic descriptions run to 75 characters and the
     card holds ~30 per line, so two lines cut nearly all of them mid-sentence. */
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.hb-card-go {
  margin-top: auto; padding-top: 4px; display: inline-flex; align-items: center; gap: 5px;
  font-family: var(--font-family); font-size: 0.82rem; font-weight: 650; color: #2c4f9e;
}
.hb-card-go svg { width: 13px; height: 13px; }
@media (hover: hover) {
  .hb-card:hover { border-color: color-mix(in srgb, #1d4ed8 30%, transparent); transform: translateY(-1px); }
}

@media (max-width: 1023px) {
  .hb-grid { grid-template-columns: 1fr; }
  .hb-hero .tdi-card .tdi-briefcol { max-width: none; }
}
@media (max-width: 560px) {
  .home-featbriefs { padding: 16px 14px 18px; }
  .hb-cards { grid-template-columns: 1fr; }
  .hb-all { font-size: 0.8rem; }
}

/* ═══ revamp983 — site footer (#img562) ════════════════════════════════════
   Only pages that exist are linked — no placeholder Blog/Careers/Press. */

