.nf-tab.is-active { background: #2c4f9e; color: #fff; font-weight: 600; }
.nf-tab--more { border-color: color-mix(in srgb, #2f4d9e 16%, transparent); color: #2c4f9e; }
@media (hover: hover) {
  .nf-tab:not(.is-active):hover { color: #1d4ed8; background: color-mix(in srgb, #1d4ed8 7%, transparent); }
}
.nf-tab:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; }

@media (max-width: 700px) {
