}
.hf-card--prompts .hq-row--prompt .hq-row-ic svg { width: 15px !important; height: 15px !important; }
.hf-card--prompts .hq-row-tx { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.hf-card--prompts .hq-row--prompt .hq-row-name {
