.tdi-meta-sep { width: 1px; height: 11px; background: currentColor; opacity: .28; }
.tdi-metarow .tdi-date { display: inline-flex; align-items: center; gap: 8px; }
.tdi-metarow .tdi-stamp-val,
.tdi-metarow .tdi-stamp-ed {
