.tdi-card--hero2 .tdi-summary { margin: 0 0 13px !important; }
.tdi-card--hero2 .tdi-actions { margin-top: 0 !important; }

@media (max-width: 1023px) {
  .topic-home .tdi-card--hero2 .tdi-briefcol,
  .hb-hero .tdi-card .tdi-briefcol { max-width: none !important; }
