}
.tbh-titlerow + .tbh-desc { margin-top: 0.5rem; }

/* ── Columns whenever NOT tabbed: news left, briefing + tools rail right. ── */
body:not(.tt-on) .topic-band .topic-home {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 384px;
  gap: 0 2rem; align-items: start;
}
body:not(.tt-on) .topic-band .topic-home > .aii-tabhead-spacer { grid-column: 1 / -1; grid-row: 1; }
