body:not(.tt-on) .topic-band .topic-home > .topic-viewtabs { display: none; }
body:not(.tt-on) .topic-band .topic-home > .topic-news-wrap { grid-column: 1; grid-row: 4; min-width: 0; margin-top: 0 !important; }
body:not(.tt-on) .topic-band .topic-home > .topic-top {
  grid-column: 2; grid-row: 4;
  display: flex !important; grid-template-columns: none !important;
  flex-direction: column; gap: 12px;
  margin-top: 0 !important;
}
body:not(.tt-on) .topic-band .topic-home .topic-top.is-di-open,
body:not(.tt-on) .topic-band .topic-home .topic-top.is-pr-open {
  display: flex !important; grid-template-columns: none !important;
}
body:not(.tt-on) .topic-band .topic-home .topic-top.is-di-open .tpr-card,
body:not(.tt-on) .topic-band .topic-home .topic-top.is-pr-open .tdi-card { animation: none; }
body:not(.tt-on) .topic-band .topic-home .tdi-card--hero2 .tdi-briefcol { max-width: 100% !important; }
body:not(.tt-on) .topic-band .topic-home .tdi-metarow { flex-wrap: wrap !important; white-space: normal !important; }
body:not(.tt-on) .topic-band .topic-home #section-newsfeed .news-list { margin-top: 12px !important; }

/* ── Section heads (#img721-724): "Latest News" a step smaller, the rail's
      "AI Briefing" / "AI Research Tools" identical and top-aligned with it —
      one shared treatment. The in-card heads they replace go. ── */
body:not(.tt-on) .topic-band .topic-home .newsfeed-title,
.trail-head {
  font-family: var(--font-display, var(--font-family));
  font-size: 1.24rem !important; font-weight: 750 !important;
