  margin: 0 !important; line-height: 1.25 !important;
}
.trail-head { display: block; padding-bottom: 12px; border-bottom: 2px solid #e0e5ee; margin-bottom: 12px !important; }
body:not(.tt-on) .topic-band .topic-home .newsfeed-head { padding-top: 0 !important; margin-top: 0 !important; }
body.tt-on .trail-head { display: none !important; }
/* The rail cards lose their internal heads: the eyebrow leaves the briefing
   card, and the tools card's title/sub leave when it's closed. */
body:not(.tt-on) .topic-band .topic-home .tdi-card .tdi-eyebrow { display: none !important; }
body:not(.tt-on) .topic-band .topic-home .tpr-card:not(.is-open) .tpr-head,
