body:not(.tt-on) .topic-band .topic-home .tpr-card { padding-top: 0.4rem !important; }

/* ── The tools list is a plain list, not a card of chrome (#img726): no card
      box, no pager dots, group labels for Topic-Specific / Evergreen. ── */
.topic-band .topic-home .tpr-card { border: 0 !important; background: none !important; box-shadow: none !important; padding-left: 0 !important; padding-right: 0 !important; }
.topic-band .topic-home .tpr-dots { display: none !important; }
.topic-band .topic-home .tpr-list { border-top: 0 !important; border-bottom: 0 !important; }
.tpr-grouplabel {
  list-style: none;
  padding: 14px 0 6px;
  font-family: var(--font-family); font-size: 0.78rem; font-weight: 700;
  letter-spacing: 0.07em; text-transform: uppercase; color: #6b7a92;
}
.tpr-list > .tpr-grouplabel:first-child { padding-top: 2px; }
/* Every prompt row shows; with the whole list present the foot is redundant. */
.topic-top-side .tpr-row:nth-child(n + 5) { display: block !important; }
body:not(.tt-on) .topic-band .topic-home .tpr-card:not(.is-open) .tpr-go { display: none !important; }

/* ── The view tabs: quiet underline style (#img727), not a heavy pill. ── */
.topic-viewtabs {
  display: flex; align-items: center; gap: 22px;
  margin: 0.9rem 0 0.2rem;
  padding: 0 0 0;
  border-bottom: 1px solid color-mix(in srgb, #2f4d9e 12%, transparent);
}
.tvt {
  position: relative;
  border: 0; background: none; cursor: pointer;
  padding: 9px 2px 11px; border-radius: 0;
  font-family: var(--font-family); font-size: 0.93rem; font-weight: 600;
  color: #5b6b8c; transition: color .14s ease;
}
.tvt::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -1px;
  height: 3px; border-radius: 3px 3px 0 0; background: transparent;
  transition: background .14s ease;
}
.tvt.is-active { background: none; color: #14204a; }
.tvt.is-active::after { background: #1e3a8a; }
@media (hover: hover) { .tvt:not(.is-active):hover { color: #14204a; background: none; } }

/* ── Change Topic rides the right edge of the grey topic bar. ── */
#sub-header.is-subnav .topic-subnav-inner { display: flex; align-items: center; }
#sub-header.is-subnav .topic-subnav-inner > .topic-subnav-picker,
