#sub-header.is-subnav .topic-subnav-inner > .subnav-ident-sep { display: none !important; }

/* ── One-column news band (1160 > content ≥ 900). ── */
body.tnews-1col .topic-band #section-newsfeed .news-list { grid-template-columns: 1fr !important; }

/* ═════════════════ TABBED MODE (body.tt-on) ═════════════════ */

/* Which section shows. */
body.tt-on .topic-band .topic-home:not(.tview-brief):not(.tview-tools) > .topic-top { display: none !important; }
body.tt-on .topic-band .topic-home.tview-brief > .topic-news-wrap { display: none !important; }
body.tt-on .topic-band .topic-home.tview-brief .topic-top-side { display: none !important; }
body.tt-on .topic-band .topic-home.tview-tools > .topic-news-wrap { display: none !important; }
body.tt-on .topic-band .topic-home.tview-tools .topic-top-main { display: none !important; }
body.tt-on .topic-band .topic-home.tview-brief > .topic-top,
body.tt-on .topic-band .topic-home.tview-tools > .topic-top {
  display: flex !important; grid-template-columns: none !important;
  flex-direction: column; margin-top: 0.8rem !important;
}

/* Chrome: the grey subnav is always on and owns identity; the body head goes. */
body.tt-on.app-mode:not(.home-mode) #sub-header.is-subnav {
  opacity: 1 !important; visibility: visible !important;
  transform: none !important; pointer-events: auto !important;
}
body.tt-on .topic-band .topic-home > .topic-bodyhead { display: none !important; }
body.tt-on .topic-band .topic-home > .aii-tabhead-spacer { display: none; }
html body.tt-on.app-mode.sticky-always.has-subnav:not(.home-search):has(.topic-home) #content,
