}
body.tt-on.app-mode .topic-band.topic-layout { padding-top: 0 !important; }
#sub-header.is-subnav .topic-subnav-inner { padding-top: 12px !important; padding-bottom: 12px !important; }

/* Sticky tabs attached under the subnav. */
body.tt-on .topic-band .topic-viewtabs {
  position: sticky;
  top: calc(var(--nav-h) + var(--subnav-height, 58px));
  z-index: 60;
  background: #f8f9fc;
  margin: 0 -2rem !important;
  padding: 2px 2rem 0;
  border-bottom: 1px solid #e5e9f2;
}
@media (max-width: 899.98px) {
  /* Below 900 #content is the scroll container and sticky offsets resolve
     against its padding box — the tabs go fixed and the pad reserves them. */
  body.tt-on .topic-band .topic-viewtabs {
    position: fixed;
    top: calc(var(--nav-h) + var(--subnav-height, 53px));
    left: 0; right: 0;
    margin: 0 !important;
    padding: 2px 1rem 0;
  }
  html body.tt-on.app-mode.sticky-always.has-subnav:not(.home-search):has(.topic-home) #content,
  html body.tt-on.app-mode.sticky-always.has-subnav:has(.topic-home) #content {
    padding-top: calc(var(--nav-h) + var(--subnav-height, 53px) + 46px) !important;
  }
}

/* News tab: the head goes (the tab is the label). revamp1077: the first card no
   longer keeps a top border — the tab strip's own faint bottom rule is the
   divider above the first story, so a second line just doubled it. */
