body.tt-on .topic-band .topic-home:not(.tview-brief):not(.tview-tools) #section-newsfeed .newsfeed-head { display: none !important; }
body.tt-on .topic-band .topic-home > .topic-news-wrap { margin-top: 10px !important; }
body.tt-on .topic-band .topic-home #section-newsfeed .news-list { margin-top: 0 !important; }
