body.tt-on .tview-brief .tdi-topiclabel--inline { display: none !important; }
body.tt-on .tview-brief .topic-top,
body.tt-on .tview-brief .topic-top-main,
body.tt-on .tview-brief .tdi-card { width: 100% !important; max-width: none !important; }
body.tt-on .tview-brief .tdi-headclose,
body.tt-on .tview-brief .tdi-closefoot { display: none !important; }
body.tt-on .tview-brief .tdi-card.is-open .tdi-bodygrid,
body.tt-on .tview-brief .tdi-card.is-open .tdi-art { display: none !important; }
body.tt-on .tview-brief .tdi-openhead > *:not(.tdi-openhead-meta) { display: none !important; }
body.tt-on .tview-brief .tdi-openhead { margin-bottom: 0 !important; border-bottom: 0 !important; }
body.tt-on .tview-brief .tdi-openhead-meta,
body.tt-on .tview-brief .tdi-openhead-meta * {
  font-family: var(--font-family) !important;
  font-size: 0.8rem !important; line-height: 1.2 !important;
  font-weight: 700 !important; color: #52618a !important;
  letter-spacing: 0.08em !important; text-transform: uppercase !important;
  margin: 0 !important; padding: 0 !important;
}
body.tt-on .tview-brief .tdi-openhead-meta {
  display: flex !important; align-items: center !important; gap: 10px !important;
  border-bottom: 0 !important;
}
body.tt-on .tview-brief .tdi-openhead-meta .tdi-stamp-edwrap,
body.tt-on .tview-brief .tdi-openhead-meta .tdi-date { display: inline-flex !important; align-items: center !important; gap: 10px !important; }
body.tt-on .tview-brief .tdi-openhead-meta .tdi-stamp-sep,
body.tt-on .tview-brief .tdi-openhead-meta .tdi-meta-sep {
  display: inline-block !important;
  width: 1px !important; height: 11px !important; opacity: .35 !important;
  margin: 0 !important; padding: 0 !important;
  background: currentColor !important; border-radius: 0 !important;
}
body.tt-on .tview-brief .tdi-openhead-meta > .tdi-stamp-sep:first-child { display: none !important; }
body.tt-on .tview-brief .tdi-openhead-meta::after,
