}
body.tt-on .tview-brief .tdi-expand-inner { padding-left: 0 !important; padding-right: 0 !important; }
body.tt-on .tview-brief .tdi-card .di-prov2,
body.tt-on .tview-brief [data-di-host] .di-prov2,
body.tt-on .tview-brief .di-prov2 {
