/* ============================================================
   revamp1017 — the homepage tab stack joins the subnav (#img805-807)
   ============================================================ */

@media (max-width: 1199.98px) {
  /* body.tt-on can't gate these: home is not .topic-band, and the stack has to
     pin even when the sidebar is docked. The tab widths are what matter. */
  /* NORMAL FLOW, not fixed. These rows live inside #content, which carries
     `overflow-x: clip` — and clip (unlike hidden) clips fixed descendants, so
     a fixed row measured perfectly and painted nothing. Topic pages escape it
     only because their #content is itself fixed. In flow the rows sit flush
     under the bars at rest, which is the attached look, and they scroll with
     the page instead of fighting the clip. */
  body.home-search.tt-on .home-viewtabs,
  body.home-search.tt-on .home-v2 .nf-tabs {
    position: static !important;
    margin: 0 !important;
    background: #f8f9fc;
    border-bottom: 1px solid #e5e9f2;
    width: auto;
  }
  body.home-search.tt-on .home-viewtabs {
    height: 46px; padding: 0 2rem !important;
    border-top: 0 !important;
  }
  body.home-search.tt-on .home-v2 .nf-tabs {
    height: 46px; padding: 0 2rem !important;
    display: flex !important; align-items: center; flex-wrap: nowrap !important;
    overflow-x: auto; scrollbar-width: none; gap: 8px;
    border-top: 0 !important;
  }
  body.home-search.tt-on .home-v2 .nf-tabs::-webkit-scrollbar { display: none; }
  body.home-search.tt-on .home-v2 .nf-tab { flex: 0 0 auto; }
  /* "More +" pins to the end of the scroll rail and opens the topic list. */
  body.home-search.tt-on .home-v2 .nf-more--tabs {
    flex: 0 0 auto; margin-left: 4px; white-space: nowrap;
    font-weight: 650; color: #2c4f9e; text-decoration: none;
  }
  /* The filters only belong to the news tab. */
  body.home-search.tt-on .home-v2.hview-brief .nf-tabs,
  body.home-search.tt-on .home-v2.hview-trend .nf-tabs,
  body.home-search.tt-on .home-v2.hview-tools .nf-tabs { display: none !important; }

  /* The tab IS the section label — the in-body "News Feed" head goes. */
  body.home-search.tt-on .home-v2 .newsfeed-headrow { display: none !important; }
  body.home-search.tt-on .home-v2 .newsfeed-head {
    border: 0 !important; padding: 0 !important; margin: 0 !important;
  }

  /* Content clears all three bars; the news tab reserves one row more. */
  html body.home-search.app-mode.sticky-always #content,
  html body.home-search.app-mode #content,
  body.home-search #content { padding-top: calc(var(--nav-h) + 56px) !important; }
  /* The tab rows are the first thing in the flow, so nothing else to reserve. */
  body.home-search.tt-on .home-v2 { padding-top: 0 !important; }
  body.home-search.tt-on .home-v2 .newsfeed-card { padding-top: 0 !important; }
  body.home-search.tt-on .home-v2 .news-list { margin-top: 14px !important; }
}
@media (max-width: 640px) {
  body.home-search.tt-on .home-viewtabs,
  body.home-search.tt-on .home-v2 .nf-tabs { padding: 0 1rem !important; }
}

/* ============================================================
   revamp1019 — the two column heads are ONE object (#img813/814)
   ============================================================ */
@media (min-width: 1200px) {
  /* Identical box: same size, same padding, same rule weight, same margin, so
     the heads and their separators land on the same two horizontal lines.
     Both columns also start their content at the grid row's top edge. */
  .topic-band .topic-home > .topic-news-wrap,
  .topic-band .topic-home > .topic-top { align-self: start; padding-top: 0 !important; margin-top: 0 !important; }
  .topic-band .topic-home .newsfeed-card { padding-top: 0 !important; margin-top: 0 !important; }

  /* `#topic-tab-body #section-newsfeed .newsfeed-title` carries TWO ids
     (2,3,0) and beat every class-only attempt — the news head kept 1.24rem
     while the rail head took 1.32. Match the ids and the two finally share
     one box. */
  #topic-tab-body #section-newsfeed .newsfeed-title,
  body:not(.tt-on) .topic-band .topic-home .newsfeed-title,
  body:not(.tt-on) .topic-band .topic-home .trail-head {
    font-family: var(--font-display, var(--font-family)) !important;
    font-size: 1.32rem !important;
    line-height: 1.3 !important;
    letter-spacing: -0.012em !important;
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
  }
  /* The rule belongs to the same box on both sides: the head wrapper on the
     news column, the heading itself in the rail. Identical pad + border + gap
     is what puts the two lines at the same y. */
  #topic-tab-body #section-newsfeed .newsfeed-head,
  body:not(.tt-on) .topic-band .topic-home .newsfeed-head,
  body:not(.tt-on) .topic-band .topic-home .trail-head {
