  min-height: 5.4em;
  padding: 12px 14px !important;
  margin: 2px 0 0 !important;
  line-height: 1.62 !important;
  border-radius: 10px !important;
  background: #fff !important;
  box-shadow: 0 0 0 1px color-mix(in srgb, #2f4d9e 26%, transparent) !important;
  outline: none;
}
