  letter-spacing: 0 !important; text-transform: none !important;
}
.tdi-metarow--stack .tdi-stamp-val { font-weight: 650 !important; color: #33415e !important; letter-spacing: 0 !important; text-transform: none !important; }
.tdi-metarow--stack .tdi-stamp-sep { color: #9aa6bd; }

/* ── Topic subtopic pills: light grey, a touch smaller, "More" matches ── */
.topic-bodyhead .tbh-sub,
.topic-bodyhead .tbh-more {
