  .aii-pc .aii-pc-foot > .aii-pc-btn,
  .aii-pc .aii-pc-foot > .aii-pc-submit,
  .aii-pc .aii-pc-foot .aii-pc-modelbtn {
    width: 100% !important; max-width: 100% !important; min-width: 0 !important; flex: 0 0 auto !important;
  }
  .aii-pc .aii-pc-foot > .aii-pc-btn,
  .aii-pc .aii-pc-foot .aii-pc-modelbtn { justify-content: flex-start !important; }
  .aii-pc .aii-pc-foot > .aii-pc-submit { justify-content: center !important; border-radius: 10px !important; }
